private fun questionPack0(): List<Q> = listOf(
    Q(id = "general-6be419f6483dff30", area = "Frontend", level = 1, q = "Explain the JavaScript event loop.", a = "JS has one call stack. Async callbacks wait in queues and move to the stack when it is empty. Microtasks (promises) run before macrotasks (setTimeout).", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-49afa1ffa150c280", area = "Frontend", level = 1, q = "var vs let vs const?", a = "var is function-scoped and hoisted as undefined. let and const are block-scoped with a temporal dead zone. const blocks reassignment, not mutation.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-b1d67aae0afbdfa9", area = "Frontend", level = 2, q = "What is a closure?", a = "A function that keeps access to variables from the scope where it was defined, even after that scope has finished. Used for private state, factories and callbacks.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-2e8793cd63aa05e0", area = "Frontend", level = 2, q = "useEffect vs useMemo in React?", a = "useEffect runs side effects after render, with cleanup and a dependency array. useMemo caches a computed value until its dependencies change.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-956ad5b0df20a0e4", area = "Frontend", level = 2, q = "Why do list items need keys in React?", a = "Stable unique keys let React match items between renders, so it updates or reorders them instead of remounting. Avoid array indexes if the list can change.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-f39234a688c69c19", area = "Frontend", level = 2, q = "Flexbox vs Grid?", a = "Flexbox lays out in one dimension (row or column). Grid handles rows and columns together. Flexbox suits components, Grid suits page layouts.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-f3b2ff886633ee0d", area = "Frontend", level = 3, q = "How do you improve web performance?", a = "Split and shrink bundles, lazy-load, size and compress images, use a CDN and caching, avoid layout thrashing, and measure Core Web Vitals (LCP, INP, CLS).", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-db055744f8f47a23", area = "Backend", level = 1, q = "REST vs GraphQL?", a = "REST exposes resources through URLs and HTTP verbs. GraphQL lets clients ask for exactly the fields they need from one endpoint. It cuts over-fetching but complicates caching.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-479d954faaa6de91", area = "Backend", level = 2, q = "What does idempotent mean for an API?", a = "Repeating a request has the same effect as sending it once. GET, PUT and DELETE are idempotent by design. For POST, use idempotency keys stored server-side.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-1385d9003aca042f", area = "Backend", level = 2, q = "Authentication vs authorization? JWT pitfalls?", a = "AuthN proves who you are; AuthZ decides what you may do. JWTs are stateless but hard to revoke, so use short expiry plus refresh tokens and keep secrets out of the payload.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-9a068a64fc9f4255", area = "Backend", level = 2, q = "What is the N+1 query problem?", a = "One query loads a list, then one extra query runs per item. Fix with joins, batch loading or eager fetching (JOIN FETCH in JPA).", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-29d4b65ae76aad99", area = "Backend", level = 3, q = "How do you handle race conditions?", a = "Use transactions with suitable isolation, optimistic locking (version column) or pessimistic locks, atomic operations, and idempotent consumers.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-c2dd5d6b7af119da", area = "Backend", level = 3, q = "How would you implement rate limiting?", a = "Token bucket or sliding window per user or IP, enforced at the gateway or with Redis counters. Return 429 with a Retry-After header.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-48ca5e77e30d458e", area = "Backend", level = 3, q = "Monolith vs microservices?", a = "A monolith is simpler to build and deploy. Microservices scale and deploy independently but add network failures, distributed data and ops cost. Start simple, split on clear boundaries.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-c67e1ff47c092576", area = "Mobile", level = 1, q = "Android activity lifecycle?", a = "onCreate, onStart, onResume, onPause, onStop, onDestroy. Rotation and process death recreate activities, so keep UI state in a ViewModel or saved state.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-705eb9437dead42d", area = "Mobile", level = 2, q = "What is recomposition in Jetpack Compose?", a = "Compose re-runs only the composables that read changed state. Hoist state, use remember and stable types to avoid unnecessary recomposition.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-75faebc7c42dc758", area = "Mobile", level = 2, q = "What is a retain cycle in iOS?", a = "ARC frees an object when strong references reach zero. Two objects (or a closure and self) holding each other strongly never free. Break it with weak or unowned references.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-dcae1acdfafbbf0c", area = "Mobile", level = 3, q = "Native vs Flutter vs React Native vs KMP?", a = "Native gives the best platform fidelity. Flutter and React Native share UI code. KMP shares business logic and optionally UI. Choose by team skills, performance needs and time to market.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-18b4a49267ebe313", area = "Mobile", level = 3, q = "How do you design an offline-first app?", a = "Make a local database (Room, Core Data) the source of truth, sync in the background, queue writes, define conflict rules and retry with backoff.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-4dd2a3461a201053", area = "Mobile", level = 3, q = "How do you reduce app startup time and size?", a = "Lazy-init, move heavy work off the main thread, use R8 and app bundles, compress assets and add baseline profiles.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original")
)
private fun questionPack1(): List<Q> = listOf(
    Q(id = "general-4c5dedee7a202f32", area = "Mobile", level = 3, q = "Mobile security basics?", a = "Store secrets in Keystore or Keychain, encrypt local data, pin certificates, keep keys out of the binary, obfuscate, and validate deep links.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-dcb20b3e4a17e680", area = "Database", level = 1, q = "What does ACID mean?", a = "Atomicity: all or nothing. Consistency: data stays valid. Isolation: concurrent transactions do not interfere. Durability: committed data survives crashes.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-cf184ec829cf4877", area = "Database", level = 1, q = "SQL vs NoSQL?", a = "SQL gives a fixed schema, joins and strong consistency. NoSQL gives flexible schemas and easy horizontal scale with trade-offs. Choose by access patterns.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-f7e55329d1c5e16e", area = "Database", level = 1, q = "Normalization vs denormalization?", a = "Normalizing removes redundancy and update anomalies. Denormalizing duplicates data to speed reads, at the cost of keeping copies consistent.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-3cbcddedafbef969", area = "Database", level = 3, q = "Transaction isolation levels?", a = "Read uncommitted, read committed, repeatable read, serializable. Higher levels prevent dirty reads, non-repeatable reads, then phantoms, with less concurrency.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-4d5b8bf473a26d00", area = "Database", level = 2, q = "How do you optimize a slow query?", a = "Read the EXPLAIN plan, add or fix indexes, avoid SELECT *, filter early, do not wrap indexed columns in functions, and paginate.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-eb4d241356e6c5ad", area = "Database", level = 2, q = "Common caching strategies?", a = "Cache-aside, write-through and write-back, with TTLs and invalidation. Watch for stampedes and stale data. Redis is a common choice.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-e9c8ba14fc15c1da", area = "DevOps and Cloud", level = 1, q = "Docker container vs virtual machine?", a = "Containers share the host kernel, so they are lighter and start faster. VMs run a full guest OS and isolate more strongly.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-ffa1dfa06c18588f", area = "DevOps and Cloud", level = 2, q = "Stages of a CI/CD pipeline?", a = "Commit, build, unit tests, static analysis, package, deploy to staging, integration tests, then a gated production deploy with rollback.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-8e2b690648331fe0", area = "DevOps and Cloud", level = 3, q = "Pod, Deployment and Service in Kubernetes?", a = "A Pod runs containers. A Deployment manages replicas and rollouts. A Service gives pods a stable network endpoint.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-d926c2b5c9df9462", area = "DevOps and Cloud", level = 3, q = "Blue-green vs canary deployment?", a = "Blue-green switches all traffic between two full environments. Canary sends a small share of traffic to the new version first to catch problems early.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-fded89904af541c6", area = "DevOps and Cloud", level = 3, q = "What is Infrastructure as Code?", a = "Infrastructure defined in versioned files (Terraform, CloudFormation) so environments are reproducible, reviewable and automated.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-49469aac108598f3", area = "DevOps and Cloud", level = 3, q = "Logs, metrics and traces?", a = "Logs record events, metrics show trends for alerting, and traces follow one request across services. Together they speed up root-cause analysis.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-0484a8388b85daa9", area = "System Design", level = 2, q = "Design a URL shortener.", a = "Generate unique IDs (base62 counter or hash), store id-to-URL in a key-value store, cache hot links, redirect with 301 or 302, add rate limits and analytics.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-001a18d9434c2cc2", area = "System Design", level = 3, q = "How do you scale a system horizontally?", a = "Stateless services behind a load balancer, shared cache, read replicas then sharding, async queues, and a CDN for static content.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-bbf3c0339a5153a3", area = "System Design", level = 3, q = "Explain the CAP theorem.", a = "In a network partition you must choose consistency or availability. Many systems tune this per feature, using eventual consistency where it is acceptable.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-65658ef21ed58f21", area = "System Design", level = 3, q = "When do you use a message queue?", a = "To decouple producers and consumers, absorb traffic spikes, retry failures and run async work. Kafka suits streams; RabbitMQ or SQS suit task queues.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-926f26718e532d9a", area = "System Design", level = 2, q = "Load balancing algorithms?", a = "Round robin, least connections, IP hash and weighted variants. L4 routes on network info, L7 on HTTP content.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-aeadbcbcb0f9a1e1", area = "System Design", level = 4, q = "How do you approach a system design question?", a = "Clarify requirements and scale, estimate load, sketch the high-level design, deep-dive bottlenecks, then discuss trade-offs and failure modes.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-45c76f2bd6a139cf", area = "Testing and QA", level = 1, q = "Unit vs integration vs end-to-end tests?", a = "Unit tests isolate one piece, integration tests check components together, e2e tests run full user flows. Keep many unit tests and fewer e2e (test pyramid).", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original")
)
private fun questionPack2(): List<Q> = listOf(
    Q(id = "general-a352324b920013b4", area = "Testing and QA", level = 1, q = "Mock vs stub?", a = "A stub returns canned data. A mock also verifies interactions, such as which calls were made.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-b0321164cd65847b", area = "Testing and QA", level = 2, q = "What should you automate?", a = "Stable, repetitive, high-risk regression paths. Keep exploratory testing and one-off checks manual.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-bea9d783b546ca0a", area = "Testing and QA", level = 2, q = "What makes a test flaky and how do you fix it?", a = "Shared state, timing, network or order dependence. Isolate data, use deterministic waits and fakes, and quarantine then fix the test.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-7ba0cfeb8a510e14", area = "Testing and QA", level = 2, q = "How do you test an API?", a = "Check status codes, schema, auth, validation and error paths, idempotency and performance, using contract tests plus automated suites (Postman, REST Assured).", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-96034da1b50628fb", area = "Tech Lead", level = 3, q = "How do you handle an underperforming engineer?", a = "Give early, specific feedback, find the cause (skill, clarity, motivation), set clear goals with support and checkpoints, and escalate only after documented effort.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-b97e3e2f91ee82c6", area = "Tech Lead", level = 3, q = "How do you balance tech debt and features?", a = "Make debt visible and costed, reserve regular capacity, tie fixes to business risk, and clean up while touching the same area.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-aff319ee7feb181b", area = "Tech Lead", level = 2, q = "How do you run effective code reviews?", a = "Review correctness, clarity and risk; automate style. Keep PRs small, be specific and kind, and respond quickly.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-10f88e3299eeb921", area = "Tech Lead", level = 3, q = "How do you mentor and grow engineers?", a = "Set growth goals in 1:1s, delegate stretch work with safety nets, give regular feedback and create visible opportunities.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-216f8b574a40f973", area = "Tech Lead", level = 3, q = "How do you handle technical disagreements?", a = "Hear each side, return to goals and data, prototype if cheap, then decide, commit and document the reasoning.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-c61ba369eb45abec", area = "Tech Lead", level = 4, q = "How do you estimate and reduce delivery risk?", a = "Slice work small, estimate in ranges, run spikes on unknowns early, and review risks weekly.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-6ce589e4b2eccca1", area = "Project Management", level = 1, q = "Agile vs Waterfall?", a = "Waterfall runs sequential phases with fixed scope. Agile delivers in short iterations and adapts to feedback. Waterfall fits stable, well-understood requirements.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-703622f1f8644e95", area = "Project Management", level = 1, q = "Scrum roles and events?", a = "Roles: Product Owner, Scrum Master, Developers. Events: sprint, sprint planning, daily scrum, sprint review, retrospective.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-7dc1ca78a7997ae8", area = "Project Management", level = 2, q = "How do you manage scope creep?", a = "Baseline the scope, assess each change for time, cost and risk, get stakeholder approval, and trade scope for scope.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-71585e09e08982f0", area = "Project Management", level = 3, q = "Critical path and risk management?", a = "The critical path is the longest chain of dependent tasks and sets minimum duration. Track risks in a register with probability, impact, owner and mitigation.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-cd5b4e21c27e6721", area = "Project Management", level = 3, q = "Which project metrics do you track?", a = "Velocity or throughput, cycle time, burndown, defect rate and milestone delivery. Use them to see trends, not to rank people.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-ced9d07b29e84faa", area = "Project Management", level = 3, q = "How do you resolve stakeholder conflicts?", a = "Clarify each priority, tie decisions to goals and constraints, explain trade-offs openly, and escalate with options when needed.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-2b57fc29f4fef5d0", area = "Java and Spring", level = 1, q = "What are the four pillars of OOP?", a = "Encapsulation, abstraction, inheritance and polymorphism: hide state, expose behavior, reuse and specialize types, and let one interface have many implementations.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-a6b0ffca47b98ccd", area = "Java and Spring", level = 2, q = "Abstract class vs interface?", a = "An abstract class can hold state and constructors, and a class extends only one. An interface defines a contract, can have default methods, and a class can implement many.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-f7965c3ca414db36", area = "Java and Spring", level = 3, q = "How does @Transactional work and what are its pitfalls?", a = "Spring wraps the bean in a proxy that starts and commits transactions. Calls from inside the same class bypass the proxy, and checked exceptions do not roll back by default.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
    Q(id = "general-ac44dff55c6abe61", area = "Java and Spring", level = 3, q = "How does JVM garbage collection work and how do you tune it?", a = "It reclaims unreachable objects by generation. Pick a collector (G1, ZGC) for your latency or throughput goal, size the heap, and read GC logs before changing flags.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original")
