private fun questionPack3(): List<Q> = listOf(
    Q(id = "general-2c6fb108692d22a1", area = "Python", level = 1, q = "List vs tuple?", a = "Lists are mutable. Tuples are immutable, and hashable when their items are, so they can be dict keys.", subtopic = "General", round = "Fundamentals", explanation = "", code = "", mistake = "", rubric = listOf(), followups = listOf(), sourceIds = listOf(), version = 1, reviewedAt = "", origin = "PrepDesk original"),
