    Q(id = "ai-data-path-28", area = "AI and Data", level = 4, q = "How should AI pipelines minimize personal data exposure?", a = "Limit collection and access.", subtopic = "Privacy", round = "Design", explanation = "Limit collection and access. Redact or transform where appropriate. Define retention deletion and provider contracts.", code = "", mistake = "Sending raw personal content without purpose review.", rubric = listOf("Limit collection and access", "Redact or transform where appropriate", "Define retention deletion and provider contracts"), followups = listOf("How would deletion reach training-derived artifacts?", "Walk through a concrete example of privacy and explain one trade-off."), sourceIds = listOf("google-ml", "sklearn", "postgres-schema", "owasp-llm"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
