    Q(id = "ai-data-path-30", area = "AI and Data", level = 4, q = "How should a team respond to a model producing harmful regressions?", a = "Limit exposure and restore a validated version.", subtopic = "Incident recovery", round = "Design", explanation = "Limit exposure and restore a validated version. Preserve redacted diagnostic evidence. Analyze data model and serving changes.", code = "", mistake = "Continuing rollout because aggregate metrics look good.", rubric = listOf("Limit exposure and restore a validated version", "Preserve redacted diagnostic evidence", "Analyze data model and serving changes"), followups = listOf("Which signals justify immediate rollback?", "Walk through a concrete example of incident recovery and explain one trade-off."), sourceIds = listOf("google-ml", "sklearn", "postgres-schema"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
