    Q(id = "android-balanced-path-01", area = "Android", level = 1, q = "When should work belong in an Activity rather than a Service?", a = "Activities own interactive screen behavior.", subtopic = "App components", round = "Fundamentals", explanation = "Activities own interactive screen behavior. Services provide explicit non-screen component roles. Background execution still follows platform limits.", code = "", mistake = "Using a Service as an unrestricted permanent worker.", rubric = listOf("Activities own interactive screen behavior", "Services provide explicit non-screen component roles", "Background execution still follows platform limits"), followups = listOf("When would scheduled work be a better fit?", "Walk through a concrete example of app components and explain one trade-off."), sourceIds = listOf("android-architecture", "android-performance", "android-security", "android-testing"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "android-balanced-path-02", area = "Android", level = 1, q = "What does declaring an exported component imply?", a = "Other applications may reach it under applicable rules.", subtopic = "Manifest", round = "Fundamentals", explanation = "Other applications may reach it under applicable rules. Validate incoming requests and permissions. Export only intended external entry points.", code = "", mistake = "Exporting internal components unnecessarily.", rubric = listOf("Other applications may reach it under applicable rules", "Validate incoming requests and permissions", "Export only intended external entry points"), followups = listOf("How would you test hostile intent input?", "Walk through a concrete example of manifest and explain one trade-off."), sourceIds = listOf("android-architecture", "android-performance", "android-security", "android-testing"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "android-balanced-path-03", area = "Android", level = 3, q = "How would you profile slow Android cold startup?", a = "Measure a release-like build on representative hardware.", subtopic = "Startup", round = "Debugging", explanation = "Measure a release-like build on representative hardware. Separate initialization storage and rendering costs. Defer nonessential work after useful first content.", code = "", mistake = "Measuring only a warm debug launch.", rubric = listOf("Measure a release-like build on representative hardware", "Separate initialization storage and rendering costs", "Defer nonessential work after useful first content"), followups = listOf("Which initialization can be lazy?", "Walk through a concrete example of startup and explain one trade-off."), sourceIds = listOf("android-architecture", "android-performance", "android-security", "android-testing"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "android-balanced-path-04", area = "Android", level = 3, q = "How would you avoid an injected object outliving its owner?", a = "Match dependency scope to lifecycle ownership.", subtopic = "Dependency injection", round = "Debugging", explanation = "Match dependency scope to lifecycle ownership. Avoid storing short-lived UI references in long-lived objects. Test cleanup on screen exit.", code = "", mistake = "Injecting an Activity into a global singleton.", rubric = listOf("Match dependency scope to lifecycle ownership", "Avoid storing short-lived UI references in long-lived objects", "Test cleanup on screen exit"), followups = listOf("How should a repository access application-level services?", "Walk through a concrete example of dependency injection and explain one trade-off."), sourceIds = listOf("android-architecture", "android-performance", "android-security", "android-testing"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "android-balanced-path-05", area = "Android", level = 3, q = "How would Room writes preserve a multi-table invariant?", a = "Use a database transaction for related writes.", subtopic = "Concurrency", round = "Debugging", explanation = "Use a database transaction for related writes. Validate all required changes before commit. Test failure rollback and concurrent behavior.", code = "", mistake = "Executing related writes independently.", rubric = listOf("Use a database transaction for related writes", "Validate all required changes before commit", "Test failure rollback and concurrent behavior"), followups = listOf("How would cancellation affect a transaction?", "Walk through a concrete example of concurrency and explain one trade-off."), sourceIds = listOf("android-architecture", "android-performance", "android-security", "android-testing"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "android-balanced-path-06", area = "Android", level = 4, q = "How would you support old app versions during API changes?", a = "Maintain supported backward-compatible contracts.", subtopic = "Compatibility", round = "Design", explanation = "Maintain supported backward-compatible contracts. Roll out capabilities and schema changes in stages. Monitor version-specific failures.", code = "", mistake = "Removing fields before installed clients migrate.", rubric = listOf("Maintain supported backward-compatible contracts", "Roll out capabilities and schema changes in stages", "Monitor version-specific failures"), followups = listOf("How would capability negotiation help?", "Walk through a concrete example of compatibility and explain one trade-off."), sourceIds = listOf("android-architecture", "android-performance", "android-security", "android-testing"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "android-balanced-path-07", area = "Android", level = 4, q = "How would you govern Android SDK dependencies?", a = "Review security privacy license and maintenance.", subtopic = "Supply chain", round = "Design", explanation = "Review security privacy license and maintenance. Measure startup size and native compatibility. Track versions actually included in release artifacts.", code = "", mistake = "Adding SDKs without auditing transmitted data.", rubric = listOf("Review security privacy license and maintenance", "Measure startup size and native compatibility", "Track versions actually included in release artifacts"), followups = listOf("How would you respond to a vulnerable transitive SDK?", "Walk through a concrete example of supply chain and explain one trade-off."), sourceIds = listOf("android-architecture", "android-performance", "android-security", "android-testing"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "android-balanced-path-08", area = "Android", level = 4, q = "How would you decide between single and multi-module Android architecture?", a = "Choose boundaries from capabilities and ownership.", subtopic = "Architecture strategy", round = "Design", explanation = "Choose boundaries from capabilities and ownership. Compare build isolation and dependency costs. Measure benefits before broad restructuring.", code = "", mistake = "Creating modules solely to maximize module count.", rubric = listOf("Choose boundaries from capabilities and ownership", "Compare build isolation and dependency costs", "Measure benefits before broad restructuring"), followups = listOf("How would you prevent feature dependency cycles?", "Walk through a concrete example of architecture strategy and explain one trade-off."), sourceIds = listOf("android-architecture", "android-performance", "android-security", "android-testing"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "android-balanced-path-09", area = "Android", level = 4, q = "Which quality signals should govern an Android release?", a = "Track crashes startup and key workflow success.", subtopic = "Reliability goals", round = "Design", explanation = "Track crashes startup and key workflow success. Include representative device and OS cohorts. Define rollout pause and recovery criteria.", code = "", mistake = "Judging quality only from successful installation.", rubric = listOf("Track crashes startup and key workflow success", "Include representative device and OS cohorts", "Define rollout pause and recovery criteria"), followups = listOf("Which regression should stop a staged rollout?", "Walk through a concrete example of reliability goals and explain one trade-off."), sourceIds = listOf("android-architecture", "android-performance", "android-security", "android-testing"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview")
