    Q(id = "behavioral-hard-choice", area = "HR and Behavioral", level = 4, q = "Describe a difficult decision where good options had different costs.", a = "State the context, alternatives, decision criteria, trade-offs, and result, including uncertainty and responsibility.", subtopic = "Leadership judgment", round = "Behavioral", explanation = "Explain what information was available at the time and what would have changed your choice. Discuss follow-up honestly rather than rewriting the decision as inevitable after seeing the outcome.", code = "", mistake = "Evaluating your past decision only with information learned later.", rubric = listOf("Compare real alternatives", "Explain contemporaneous evidence", "Own consequences and learning"), followups = listOf("Who was affected by the decision?", "What trigger would have caused reversal?"), sourceIds = listOf("structured-interviews"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "behavioral-team-growth", area = "HR and Behavioral", level = 4, q = "Tell me about helping a team grow while maintaining delivery.", a = "Describe the specific capability gap, your intervention, how ownership changed, and evidence of improvement.", subtopic = "People leadership", round = "Behavioral", explanation = "Include capacity and trade-offs, such as mentoring time or adjusted scope. Explain what failed or required adjustment. Avoid using a single promotion as the only measure of team effectiveness.", code = "", mistake = "Taking credit for growth without describing the team's own actions.", rubric = listOf("Identify a capability gap", "Describe concrete support and ownership", "Show delivery and learning outcomes"), followups = listOf("How did you measure improvement?", "What would you change for another team?"), sourceIds = listOf("structured-interviews"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview")
)
