    Q(id = "cpp-path-05", area = "C and C++", level = 1, q = "Why must a C buffer track its length explicitly?", a = "Raw pointers carry no bounds.", subtopic = "Arrays", round = "Fundamentals", explanation = "Raw pointers carry no bounds. Operations need valid capacity and length. Check input before copying.", code = "", mistake = "Using string termination as proof of available capacity.", rubric = listOf("Raw pointers carry no bounds", "Operations need valid capacity and length", "Check input before copying"), followups = listOf("How would you prevent an off-by-one write?", "Walk through a concrete example of arrays and explain one trade-off."), sourceIds = listOf("cpp-guidelines"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
