    Q(id = "cpp-path-08", area = "C and C++", level = 1, q = "What makes undefined behavior dangerous?", a = "The language provides no outcome guarantee.", subtopic = "Undefined behavior", round = "Fundamentals", explanation = "The language provides no outcome guarantee. Optimization may assume it never occurs. Prevent invalid memory and arithmetic operations.", code = "", mistake = "Assuming observed behavior is portable correctness.", rubric = listOf("The language provides no outcome guarantee", "Optimization may assume it never occurs", "Prevent invalid memory and arithmetic operations"), followups = listOf("How would signed overflow affect reasoning?", "Walk through a concrete example of undefined behavior and explain one trade-off."), sourceIds = listOf("cpp-guidelines"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "cpp-path-09", area = "C and C++", level = 2, q = "How does RAII improve exception safety?", a = "Resources follow object lifetime.", subtopic = "RAII", round = "Scenario", explanation = "Resources follow object lifetime. Destructors release owned resources. Scope exit handles multiple control paths.", code = "", mistake = "Using manual cleanup scattered across returns.", rubric = listOf("Resources follow object lifetime", "Destructors release owned resources", "Scope exit handles multiple control paths"), followups = listOf("How would a file wrapper apply RAII?", "Walk through a concrete example of raii and explain one trade-off."), sourceIds = listOf("cpp-guidelines"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "cpp-path-10", area = "C and C++", level = 2, q = "When choose unique_ptr instead of shared_ptr?", a = "Unique ownership is simpler and explicit.", subtopic = "Smart pointers", round = "Scenario", explanation = "Unique ownership is simpler and explicit. Shared ownership has coordination overhead. Use sharing only when lifetimes require it.", code = "", mistake = "Using shared_ptr for every allocation.", rubric = listOf("Unique ownership is simpler and explicit", "Shared ownership has coordination overhead", "Use sharing only when lifetimes require it"), followups = listOf("How would ownership transfer work?", "Walk through a concrete example of smart pointers and explain one trade-off."), sourceIds = listOf("cpp-guidelines"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "cpp-path-11", area = "C and C++", level = 2, q = "What is a move operation intended to transfer?", a = "It can transfer owned resources.", subtopic = "Copy and move", round = "Scenario", explanation = "It can transfer owned resources. Moved-from objects remain valid under their contract. Do not assume every move is free.", code = "", mistake = "Reading unspecified moved-from contents as original data.", rubric = listOf("It can transfer owned resources", "Moved-from objects remain valid under their contract", "Do not assume every move is free"), followups = listOf("How would you design a movable resource wrapper?", "Walk through a concrete example of copy and move and explain one trade-off."), sourceIds = listOf("cpp-guidelines"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
