    Q(id = "cpp-path-13", area = "C and C++", level = 2, q = "Why do polymorphic base classes often need virtual destructors?", a = "Deletion through a base needs correct destruction.", subtopic = "Virtual dispatch", round = "Scenario", explanation = "Deletion through a base needs correct destruction. Virtual dispatch supports runtime behavior. Make intended deletion ownership explicit.", code = "", mistake = "Deleting derived objects through an unsafe base interface.", rubric = listOf("Deletion through a base needs correct destruction", "Virtual dispatch supports runtime behavior", "Make intended deletion ownership explicit"), followups = listOf("When would a protected destructor be appropriate?", "Walk through a concrete example of virtual dispatch and explain one trade-off."), sourceIds = listOf("cpp-guidelines"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "cpp-path-14", area = "C and C++", level = 2, q = "What do exception-safety guarantees describe?", a = "Basic safety preserves invariants and resources.", subtopic = "Exceptions", round = "Scenario", explanation = "Basic safety preserves invariants and resources. Strong safety preserves prior observable state. No-throw operations cannot propagate exceptions.", code = "", mistake = "Claiming exception safety without defining state after failure.", rubric = listOf("Basic safety preserves invariants and resources", "Strong safety preserves prior observable state", "No-throw operations cannot propagate exceptions"), followups = listOf("How would you test a failed insertion?", "Walk through a concrete example of exceptions and explain one trade-off."), sourceIds = listOf("cpp-guidelines"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "cpp-path-15", area = "C and C++", level = 2, q = "When do templates improve a C++ API?", a = "They express typed reusable operations.", subtopic = "Templates", round = "Scenario", explanation = "They express typed reusable operations. Constraints communicate valid requirements. Account for compilation and diagnostic cost.", code = "", mistake = "Writing unrestricted templates with hidden assumptions.", rubric = listOf("They express typed reusable operations", "Constraints communicate valid requirements", "Account for compilation and diagnostic cost"), followups = listOf("How would concepts clarify a requirement?", "Walk through a concrete example of templates and explain one trade-off."), sourceIds = listOf("cpp-guidelines"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "cpp-path-16", area = "C and C++", level = 2, q = "How do sanitizers complement C++ tests?", a = "They detect executed memory or concurrency violations.", subtopic = "Tests", round = "Scenario", explanation = "They detect executed memory or concurrency violations. Tests must exercise meaningful paths. They do not prove all behavior safe.", code = "", mistake = "Treating a clean sanitizer run as formal correctness.", rubric = listOf("They detect executed memory or concurrency violations", "Tests must exercise meaningful paths", "They do not prove all behavior safe"), followups = listOf("Which sanitizer fits a data race?", "Walk through a concrete example of tests and explain one trade-off."), sourceIds = listOf("cpp-guidelines"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
