    Q(id = "database-path-06", area = "Database", level = 1, q = "Why does an index speed some reads but slow writes?", a = "It supports selected access paths.", subtopic = "Indexes", round = "Fundamentals", explanation = "It supports selected access paths. Writes must maintain index entries. Storage and selectivity affect usefulness.", code = "", mistake = "Indexing every column without workload evidence.", rubric = listOf("It supports selected access paths", "Writes must maintain index entries", "Storage and selectivity affect usefulness"), followups = listOf("Which query would not benefit from your index?", "Walk through a concrete example of indexes and explain one trade-off."), sourceIds = listOf("postgres-schema", "postgres-indexes", "postgres-isolation", "postgres-explain"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
