    Q(id = "database-path-08", area = "Database", level = 1, q = "Why enforce critical invariants in the database?", a = "All writers share the same boundary.", subtopic = "Constraints", round = "Fundamentals", explanation = "All writers share the same boundary. Constraints prevent invalid persisted states. Application checks still improve feedback.", code = "", mistake = "Relying only on a pre-insert existence check.", rubric = listOf("All writers share the same boundary", "Constraints prevent invalid persisted states", "Application checks still improve feedback"), followups = listOf("How would a uniqueness race occur?", "Walk through a concrete example of constraints and explain one trade-off."), sourceIds = listOf("postgres-schema", "postgres-indexes", "postgres-isolation", "postgres-explain"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "database-path-09", area = "Database", level = 2, q = "Why can offset pagination slow down at large offsets?", a = "Earlier rows still need processing.", subtopic = "Pagination", round = "Scenario", explanation = "Earlier rows still need processing. Stable ordering is required. Keyset pagination can avoid deep skips.", code = "", mistake = "Paginating without a deterministic order.", rubric = listOf("Earlier rows still need processing", "Stable ordering is required", "Keyset pagination can avoid deep skips"), followups = listOf("How would you design a cursor for equal timestamps?", "Walk through a concrete example of pagination and explain one trade-off."), sourceIds = listOf("postgres-schema", "postgres-indexes", "postgres-isolation", "postgres-explain"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
