    Q(id = "database-path-11", area = "Database", level = 2, q = "How does column order affect a multi-column index?", a = "Predicates and ordering determine usable access paths.", subtopic = "Composite indexes", round = "Scenario", explanation = "Predicates and ordering determine usable access paths. Leading columns often shape efficiency. Validate with actual plans.", code = "", mistake = "Choosing index order alphabetically.", rubric = listOf("Predicates and ordering determine usable access paths", "Leading columns often shape efficiency", "Validate with actual plans"), followups = listOf("How would equality and range predicates interact?", "Walk through a concrete example of composite indexes and explain one trade-off."), sourceIds = listOf("postgres-schema", "postgres-indexes", "postgres-isolation", "postgres-explain"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
