    Q(id = "database-path-15", area = "Database", level = 2, q = "Why choose exact numeric types for financial amounts?", a = "Exact decimal representation preserves intended arithmetic.", subtopic = "Data types", round = "Scenario", explanation = "Exact decimal representation preserves intended arithmetic. Define precision and rounding rules. Avoid floating-point monetary assumptions.", code = "", mistake = "Storing all currency values as floating-point numbers.", rubric = listOf("Exact decimal representation preserves intended arithmetic", "Define precision and rounding rules", "Avoid floating-point monetary assumptions"), followups = listOf("How would different currency scales be modeled?", "Walk through a concrete example of data types and explain one trade-off."), sourceIds = listOf("postgres-schema", "postgres-indexes", "postgres-isolation", "postgres-explain"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "database-path-16", area = "Database", level = 2, q = "What makes a database migration test meaningful?", a = "Run upgrades on realistic prior schemas.", subtopic = "Migrations", round = "Scenario", explanation = "Run upgrades on realistic prior schemas. Verify preserved data and constraints. Test failure and recovery paths.", code = "", mistake = "Testing only fresh database creation.", rubric = listOf("Run upgrades on realistic prior schemas", "Verify preserved data and constraints", "Test failure and recovery paths"), followups = listOf("How would an interrupted backfill resume?", "Walk through a concrete example of migrations and explain one trade-off."), sourceIds = listOf("postgres-schema", "postgres-indexes", "postgres-isolation", "postgres-explain"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
