    Q(id = "database-path-18", area = "Database", level = 3, q = "How should an application handle a deadlocked transaction?", a = "The database may abort a participant.", subtopic = "Deadlocks", round = "Debugging", explanation = "The database may abort a participant. Retry the entire eligible transaction. Reduce inconsistent lock ordering.", code = "", mistake = "Retrying only the last failed statement blindly.", rubric = listOf("The database may abort a participant", "Retry the entire eligible transaction", "Reduce inconsistent lock ordering"), followups = listOf("How would you limit retries?", "Walk through a concrete example of deadlocks and explain one trade-off."), sourceIds = listOf("postgres-schema", "postgres-indexes", "postgres-isolation", "postgres-explain"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "database-path-19", area = "Database", level = 3, q = "How does a version column prevent lost updates?", a = "Writes require the expected prior version.", subtopic = "Optimistic concurrency", round = "Debugging", explanation = "Writes require the expected prior version. A mismatch exposes a conflict. Reconcile instead of silently overwriting.", code = "", mistake = "Checking a version then writing without an atomic condition.", rubric = listOf("Writes require the expected prior version", "A mismatch exposes a conflict", "Reconcile instead of silently overwriting"), followups = listOf("How should the UI present a conflict?", "Walk through a concrete example of optimistic concurrency and explain one trade-off."), sourceIds = listOf("postgres-schema", "postgres-indexes", "postgres-isolation", "postgres-explain"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
