    Q(id = "database-path-29", area = "Database", level = 4, q = "How should systems reconcile divergent replicated data?", a = "Define authoritative ownership and conflict policy.", subtopic = "Consistency", round = "Design", explanation = "Define authoritative ownership and conflict policy. Use version or causal metadata when needed. Make repair observable.", code = "", mistake = "Choosing the last arrival without business justification.", rubric = listOf("Define authoritative ownership and conflict policy", "Use version or causal metadata when needed", "Make repair observable"), followups = listOf("Which data must never use blind last-write-wins?", "Walk through a concrete example of consistency and explain one trade-off."), sourceIds = listOf("postgres-schema", "postgres-indexes", "postgres-isolation", "postgres-explain"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
