private fun questionPack25(): List<Q> = listOf(
    Q(id = "database-constraints", area = "Database", level = 1, q = "Should an application check that a username is unique before inserting it?", a = "A pre-check helps user feedback but cannot prevent races. Enforce the uniqueness rule with a database constraint.", subtopic = "Relational modeling", round = "Fundamentals", explanation = "Concurrent requests can both pass a pre-check. Define case normalization and null behavior explicitly, then translate a constraint violation into a useful application error.", code = "", mistake = "Relying only on application-side validation.", rubric = listOf("Describe the concurrent race", "Enforce a unique constraint", "Define normalization semantics"), followups = listOf("What if uniqueness is tenant-scoped?", "How should duplicate requests be handled?"), sourceIds = listOf("postgres-schema"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "database-index-cost", area = "Database", level = 1, q = "Why not create an index on every column?", a = "Indexes can speed selected reads but consume storage and add write and maintenance work.", subtopic = "Indexes", round = "Fundamentals", explanation = "Choose indexes from query filters, joins, ordering, and actual plans. Selectivity and combined predicates matter. Measure read benefit against insertion and update cost.", code = "", mistake = "Assuming an index guarantees that the planner will use it.", rubric = listOf("Explain read benefit", "Account for write/storage cost", "Use query plans to validate"), followups = listOf("When is a composite index useful?", "Why might a scan be faster?"), sourceIds = listOf("postgres-indexes", "postgres-explain"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "database-explain", area = "Database", level = 2, q = "A query is fast in development and slow in production. What evidence do you collect?", a = "Compare plans, data distribution, statistics, parameters, row counts, and I/O under representative load.", subtopic = "Query performance", round = "Debugging", explanation = "EXPLAIN ANALYZE executes the statement, so handle writes carefully. Large estimated-versus-actual row differences can indicate stale statistics or skew. Measure before and after an index or query change.", code = "", mistake = "Running EXPLAIN ANALYZE on production writes casually.", rubric = listOf("Compare representative plans", "Inspect estimate errors", "Validate an actionable change"), followups = listOf("What can a bad join estimate cause?", "How would lock waits appear?"), sourceIds = listOf("postgres-explain"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "database-lost-update", area = "Database", level = 2, q = "Two requests read stock=1 and both sell the item. How can SQL prevent this?", a = "Use an atomic conditional update or lock the row within a transaction, and check whether the update succeeded.", subtopic = "Transactions", round = "Coding", explanation = "For example, decrement only where stock > 0 and inspect affected rows. Tie reservation and order creation together according to the business invariant. Retry appropriate transaction conflicts.", code = "", mistake = "Assuming a read followed by a write is automatically safe.", rubric = listOf("Show the read/write race", "Enforce stock invariant atomically", "Handle unsuccessful updates"), followups = listOf("What if multiple items are reserved?", "How do you release expired reservations?"), sourceIds = listOf("postgres-isolation"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "database-keyset", area = "Database", level = 3, q = "A feed with millions of rows gets slower on deep pages. How would you change pagination?", a = "Use keyset pagination over a stable total order and an index matching its filter and ordering.", subtopic = "Pagination", round = "System design", explanation = "Include a tie-breaker such as ID, encode the last seen keys, and define concurrent-insert behavior. Keyset pagination trades arbitrary page jumps for efficient sequential traversal.", code = "", mistake = "Using a timestamp cursor without resolving ties.", rubric = listOf("Specify a total order", "Align cursor and index", "Explain navigation trade-offs"), followups = listOf("How do deletions affect a cursor?", "Can you support reverse navigation?"), sourceIds = listOf("postgres-indexes"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "database-isolation", area = "Database", level = 3, q = "A reporting transaction sees rows change between two reads. Is the database broken?", a = "Behavior depends on isolation level. PostgreSQL Read Committed uses a new snapshot for each command.", subtopic = "Transactions", round = "Debugging", explanation = "Choose repeatable read or serializable when required by the invariant, and account for their conflict behavior. Serializable failures require retrying the whole transaction safely.", code = "", mistake = "Assuming all databases and isolation levels share identical semantics.", rubric = listOf("Identify the isolation level", "Define the consistency requirement", "Handle transaction retries"), followups = listOf("How does write skew differ from a lost update?", "What does a long snapshot cost?"), sourceIds = listOf("postgres-isolation"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "database-schema-rollout", area = "Database", level = 4, q = "How would you rename a heavily used database column without a coordinated outage?", a = "Use an expand-and-contract rollout: add compatible structure, migrate readers/writers and data, then remove old structure.", subtopic = "Schema evolution", round = "System design", explanation = "Control backfill load and lock duration. Define who owns dual-write consistency and verify no old consumers remain. Rollback must still understand the data written by new versions.", code = "", mistake = "Dropping the old column immediately after deploying one service.", rubric = listOf("Maintain mixed-version compatibility", "Plan and verify backfill", "Define safe contraction and rollback"), followups = listOf("How do you detect forgotten consumers?", "What if the backfill is interrupted?"), sourceIds = listOf("postgres-schema", "sre-book"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "database-tenancy", area = "Database", level = 4, q = "Choose a multi-tenant data isolation strategy for a growing SaaS platform.", a = "Compare shared tables, schemas, and separate databases against isolation, operational scale, customization, and cost.", subtopic = "Data architecture", round = "Leadership", explanation = "Enforce tenant boundaries in every access path and test negative cases. Include backups, restore granularity, migrations, and noisy-neighbor limits. Document when a tenant moves to stronger isolation.", code = "", mistake = "Choosing the cheapest layout without testing cross-tenant access.", rubric = listOf("Compare isolation trade-offs", "Validate tenant access boundaries", "Plan operations and exceptions"), followups = listOf("How do you restore one tenant?", "Which workloads justify dedicated storage?"), sourceIds = listOf("postgres-schema", "owasp-api"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview")
)
