private fun questionPack31(): List<Q> = listOf(
    Q(id = "dotnet-async", area = "C# and .NET", level = 1, q = "Does async in C# always create a new thread?", a = "No. Async enables awaiting completion without blocking the caller; execution depends on the operation and scheduling context.", subtopic = "Async", round = "Fundamentals", explanation = "I/O can complete asynchronously without dedicating a thread per wait. CPU work still needs execution capacity. Use Task.Run selectively for suitable CPU work rather than wrapping all server I/O.", code = "", mistake = "Equating every Task with a dedicated thread.", rubric = listOf("Distinguish awaiting and parallel execution", "Explain I/O versus CPU work", "Choose execution deliberately"), followups = listOf("When does an async method run synchronously?", "What if a task is already complete?"), sourceIds = listOf("dotnet-async"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "dotnet-blocking", area = "C# and .NET", level = 1, q = "Why can calling .Result on an async operation cause problems?", a = "It blocks a thread and can deadlock in some synchronization contexts or exhaust capacity under load.", subtopic = "Async", round = "Debugging", explanation = "Await through the call chain. A classic UI deadlock occurs when completion needs the blocked context. On servers, thread-pool starvation can still be a problem even without that UI context.", code = "", mistake = "Claiming every .Result call causes exactly the same deadlock.", rubric = listOf("Explain blocking", "Describe context-dependent deadlock", "Propagate async through callers"), followups = listOf("Does ConfigureAwait solve every problem?", "How does server starvation differ?"), sourceIds = listOf("dotnet-async"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "dotnet-queries", area = "C# and .NET", level = 2, q = "An EF Core page makes one database query per row. How do you investigate it?", a = "Inspect generated SQL and query counts, then use deliberate projection or related-data loading to avoid an N+1 pattern.", subtopic = "EF Core", round = "Debugging", explanation = "Fetch only required fields and bound the result size. Compare joins and split queries for the data shape; either can have costs. Verify performance with production-like cardinality.", code = "", mistake = "Loading every navigation property to avoid thinking about query shape.", rubric = listOf("Measure actual query count", "Choose projection/loading strategy", "Bound and benchmark results"), followups = listOf("When do split queries help?", "What is tracking overhead?"), sourceIds = listOf("ef-querying"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "dotnet-cancellation", area = "C# and .NET", level = 2, q = "Implement a cancellable endpoint that calls several downstream operations.", a = "Pass the CancellationToken through supported APIs, await owned tasks, and define whether failure cancels sibling work.", subtopic = "Async", round = "Coding", explanation = "Dispose cancellation sources you own and handle cancellation separately from ordinary failure. Cancellation is cooperative, so blocking libraries may not stop immediately.", code = "", mistake = "Creating a token and never passing it to downstream work.", rubric = listOf("Propagate cancellation", "Define task ownership", "Distinguish cancellation and failure"), followups = listOf("When should tokens be linked?", "How do you enforce an overall timeout?"), sourceIds = listOf("dotnet-async"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "dotnet-pagination", area = "C# and .NET", level = 3, q = "Design an EF Core query for a large scrolling feed.", a = "Project a bounded page in a stable order and use keyset pagination where sequential navigation is sufficient.", subtopic = "EF Core", round = "System design", explanation = "Match indexes to filtering and cursor keys. Include a unique tie-breaker and inspect generated SQL. Avoid pulling all rows into memory before applying filters.", code = "", mistake = "Calling ToList before pagination and then filtering in memory.", rubric = listOf("Keep filtering on the server", "Define stable cursors", "Verify generated SQL and indexes"), followups = listOf("How do you support backwards navigation?", "When is offset pagination acceptable?"), sourceIds = listOf("ef-querying"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "dotnet-throughput", area = "C# and .NET", level = 3, q = "A .NET API uses async everywhere but still degrades under load. What do you measure?", a = "Measure thread-pool pressure, blocking paths, outstanding requests, database pools, and downstream latency.", subtopic = "Async services", round = "Debugging", explanation = "Async does not create unlimited capacity. Bound concurrency and queue growth, remove sync-over-async calls, and compare throughput and tail latency under degraded dependencies.", code = "", mistake = "Assuming async keywords prove the system cannot block.", rubric = listOf("Measure bottleneck resources", "Find hidden blocking", "Bound concurrency and verify recovery"), followups = listOf("When does extra concurrency reduce throughput?", "How would you identify pool starvation?"), sourceIds = listOf("dotnet-async", "sre-overload"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "dotnet-upgrades", area = "C# and .NET", level = 4, q = "Plan a major .NET upgrade for a regulated production platform.", a = "Inventory compatibility risks, preserve behavior through contract tests, and use staged deployment with auditable recovery.", subtopic = "Platform evolution", round = "Leadership", explanation = "Include serializers, EF migrations, native integrations, and runtime images. Assign owners and exception expiry dates. Validate operational behavior as well as compilation.", code = "", mistake = "Treating a successful build as complete upgrade evidence.", rubric = listOf("Map compatibility risks", "Validate representative contracts", "Plan rollout and recovery ownership"), followups = listOf("What if a serializer changes defaults?", "How do you maintain mixed versions?"), sourceIds = listOf("dotnet-async", "ef-querying"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "dotnet-data-boundary", area = "C# and .NET", level = 4, q = "Several services share EF entities directly. What risks would you address?", a = "Separate internal persistence models from public contracts and define ownership of schema and writes.", subtopic = "Architecture", round = "System design", explanation = "Shared entities can spread schema coupling and tracking assumptions across services. Introduce explicit DTOs and compatibility tests incrementally; do not migrate everything in one release.", code = "", mistake = "Exposing the complete database model as an API contract.", rubric = listOf("Define data ownership", "Separate persistence and API models", "Plan compatible migration"), followups = listOf("How do consumers request new fields?", "When can sharing a model be reasonable?"), sourceIds = listOf("ef-querying", "postgres-schema"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview")
)
