    Q(id = "flutter-widgets", area = "Flutter", level = 1, q = "How do widget configuration and State differ in Flutter?", a = "Widgets describe immutable configuration; a State object can retain mutable state across compatible rebuilds.", subtopic = "Widget model", round = "Fundamentals", explanation = "The framework uses type and identity to decide whether state survives. Rebuilding widgets is normal; choose state ownership around user lifetimes rather than avoiding every build.", code = "", mistake = "Assuming rebuilding always destroys all associated state.", rubric = listOf("Separate configuration and state", "Explain rebuilds", "Define state lifetime"), followups = listOf("How do keys affect identity?", "When is a StatelessWidget sufficient?"), sourceIds = listOf("flutter-architecture"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "flutter-build", area = "Flutter", level = 1, q = "A network request starts every time a Flutter widget builds. What is wrong?", a = "Build can run repeatedly. Own the request in a suitable lifecycle or state layer rather than starting side effects on every build.", subtopic = "Rendering", round = "Debugging", explanation = "Cache or manage the operation for the desired lifetime and define refresh behavior. Render loading, error, and result state separately. Test parent rebuilds and navigation.", code = "", mistake = "Treating build as a one-time initialization callback.", rubric = listOf("Keep rendering free of repeated side effects", "Own request lifetime", "Define refresh and failure states"), followups = listOf("What if widget parameters change?", "How should errors be retried?"), sourceIds = listOf("flutter-architecture"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "flutter-dispose", area = "Flutter", level = 2, q = "An async result calls setState after a Flutter screen closes. How do you handle it?", a = "Cancel owned work or ignore obsolete results, and check that UI state is still valid before applying it.", subtopic = "Lifecycle", round = "Debugging", explanation = "Dispose controllers and subscriptions. A mounted check can avoid an invalid update but does not automatically stop wasted work or prevent stale results after parameters change.", code = "", mistake = "Using mounted as the entire cancellation strategy.", rubric = listOf("Clean up owned resources", "Guard obsolete results", "Handle parameter changes"), followups = listOf("How do you cancel a stream subscription?", "What should happen to durable work?"), sourceIds = listOf("flutter-architecture"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "flutter-list", area = "Flutter", level = 2, q = "Build a long Flutter feed without rendering every item up front.", a = "Use a lazy list builder with stable item identity and lightweight row builds.", subtopic = "Rendering", round = "Coding", explanation = "Bound image decoding and caching, paginate data, and preserve appropriate scroll state. Measure frame timing; lazy widgets alone do not fix expensive work inside every visible row.", code = "", mistake = "Loading all remote data because the widgets are lazy.", rubric = listOf("Render rows lazily", "Bound data/image work", "Measure frame performance"), followups = listOf("How would you support variable-height rows?", "What should persist on navigation?"), sourceIds = listOf("flutter-performance"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "flutter-isolate", area = "Flutter", level = 3, q = "A Flutter app drops frames while parsing a large payload. Would async fix it?", a = "Async does not move CPU work to another isolate. Measure parsing cost and offload suitable computation when transfer overhead is justified.", subtopic = "Performance", round = "Debugging", explanation = "Keep UI work on its owning isolate and send transferable data. Small jobs can cost more to offload than to run locally. Validate on representative devices and payload sizes.", code = "", mistake = "Equating a Future with CPU parallelism.", rubric = listOf("Identify CPU frame blocking", "Choose suitable isolate work", "Measure transfer and scheduling cost"), followups = listOf("How do you handle stale results?", "When is chunking better?"), sourceIds = listOf("flutter-performance"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "flutter-architecture", area = "Flutter", level = 3, q = "Design Flutter state for an offline task manager with syncing.", a = "Separate presentation state from repositories and durable local data, with explicit sync and conflict policies.", subtopic = "App architecture", round = "System design", explanation = "A state library does not determine durability. Use stable task IDs, durable pending operations, and clear error/retry states. Test app termination while saving and syncing.", code = "", mistake = "Keeping the only copy of pending edits in a UI notifier.", rubric = listOf("Separate state ownership", "Persist edits and retries", "Define conflict and failure behavior"), followups = listOf("How do you represent deletions?", "Which state should survive reinstall?"), sourceIds = listOf("flutter-architecture"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "flutter-platform", area = "Flutter", level = 4, q = "A Flutter app targets mobile and desktop. What should vary by platform?", a = "Share domain behavior where useful while adapting input, navigation, layout, accessibility, and platform services.", subtopic = "Multiplatform strategy", round = "System design", explanation = "Validate plugin support, lifecycle behavior, and performance on every target. Use platform boundaries for capabilities rather than scattering platform checks throughout business logic.", code = "", mistake = "Assuming a responsive layout alone produces a good desktop app.", rubric = listOf("Define shared and platform capabilities", "Adapt input and accessibility", "Validate plugins and performance"), followups = listOf("How do you handle missing platform APIs?", "Which tests can be shared?"), sourceIds = listOf("flutter-architecture", "w3c-accessibility"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "flutter-governance", area = "Flutter", level = 4, q = "Set a performance policy for a large Flutter product.", a = "Define device-based frame, startup, memory, and network budgets, then measure representative user journeys continuously.", subtopic = "Engineering strategy", round = "Leadership", explanation = "Keep profiling comparable across releases and make regressions actionable for owners. Approve exceptions with evidence. Optimize measured hot paths while preserving maintainability and accessibility.", code = "", mistake = "Judging performance only on a flagship development device.", rubric = listOf("Set user-journey budgets", "Measure representative targets", "Assign regression and exception owners"), followups = listOf("How do you investigate a startup regression?", "Which metrics should block a release?"), sourceIds = listOf("flutter-performance"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview")
