    Q(id = "frontend-path-32", area = "Frontend", level = 4, q = "How should a product handle an unavailable critical API?", a = "Preserve useful cached state and drafts.", subtopic = "Resilience", round = "Design", explanation = "Preserve useful cached state and drafts. Offer clear recovery actions. Bound retries and communicate limitations.", code = "", mistake = "Turning every failure into an endless loading screen.", rubric = listOf("Preserve useful cached state and drafts", "Offer clear recovery actions", "Bound retries and communicate limitations"), followups = listOf("Which operations can remain useful offline?", "Walk through a concrete example of resilience and explain one trade-off."), sourceIds = listOf("mdn-javascript", "w3c-accessibility", "http-caching", "owasp-api"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview")
