private fun questionPack40(): List<Q> = listOf(
    Q(id = "frontend-semantics", area = "Frontend", level = 1, q = "Why use a button element instead of a clickable div for an action?", a = "A native button supplies action semantics and standard keyboard behavior; a div requires that behavior to be built and tested.", subtopic = "Accessibility", round = "Fundamentals", explanation = "Include accessible naming, focus visibility, and appropriate disabled behavior. Native semantics reduce work but do not excuse poor labels or unreachable controls.", code = "", mistake = "Adding a click handler and considering accessibility finished.", rubric = listOf("Use meaningful semantics", "Support keyboard and focus", "Provide an accessible name"), followups = listOf("When should an anchor be used?", "How would you test without a mouse?"), sourceIds = listOf("w3c-accessibility"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "frontend-layout", area = "Frontend", level = 1, q = "A modal looks correct but keyboard focus moves behind it. What is missing?", a = "Modal interaction needs deliberate focus entry, containment while open, and return to the triggering control.", subtopic = "CSS and rendering", round = "Debugging", explanation = "Use appropriate dialog semantics and test escape/close behavior and assistive technologies. Hiding content visually is not enough to define keyboard interaction.", code = "", mistake = "Treating a high z-index as a complete modal implementation.", rubric = listOf("Manage focus entry and return", "Contain modal interaction", "Test keyboard and naming"), followups = listOf("What if the trigger disappears?", "How should nested dialogs behave?"), sourceIds = listOf("w3c-accessibility"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "frontend-cache", area = "Frontend", level = 2, q = "Users see stale frontend assets after a release. How do you design caching?", a = "Use content-versioned asset URLs and appropriate cache directives, while giving the entry document a deliberate freshness policy.", subtopic = "HTTP caching", round = "Debugging", explanation = "Cache behavior involves browsers, CDNs, and service workers. Identify the layer serving old data before changing headers. Personal data needs a different policy from public static assets.", code = "", mistake = "Disabling all caching instead of diagnosing the stale layer.", rubric = listOf("Version immutable assets", "Define document freshness", "Inspect browser/CDN behavior"), followups = listOf("What does no-cache mean?", "How would a service worker affect this?"), sourceIds = listOf("http-caching"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "frontend-form", area = "Frontend", level = 2, q = "Design a form with async validation and accessible errors.", a = "Keep field values and validation state clear, associate errors with fields, and validate again at the server boundary.", subtopic = "Forms", round = "Coding", explanation = "Prevent stale validation responses from overwriting newer input. Preserve typed data on failure and guide focus appropriately after submission. Client validation improves feedback, not server trust.", code = "", mistake = "Treating client-side validation as a security boundary.", rubric = listOf("Associate errors and fields", "Handle asynchronous races", "Validate on the server"), followups = listOf("How do you announce a form-level error?", "When should validation run?"), sourceIds = listOf("w3c-accessibility", "owasp-api"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "frontend-loading", area = "Frontend", level = 3, q = "A web app loads megabytes of JavaScript before showing its main workflow. What would you change?", a = "Measure critical-path assets and user interactions, then split unnecessary code and defer suitable work.", subtopic = "Performance", round = "System design", explanation = "Account for parsing and execution on slow devices as well as transfer size. Prefetch only with evidence and monitor failures at loading boundaries. Keep essential controls usable early.", code = "", mistake = "Optimizing bundle size while ignoring main-thread execution cost.", rubric = listOf("Measure the user critical path", "Reduce initial execution and data", "Validate loading and failure behavior"), followups = listOf("When can code splitting hurt?", "What would you test on a slow device?"), sourceIds = listOf("mdn-javascript", "http-caching"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "frontend-race", area = "Frontend", level = 3, q = "Navigating quickly between records sometimes displays the wrong record. How do you reason about this?", a = "Tie each response to the active record/request and prevent obsolete responses from changing the current view.", subtopic = "Browser async state", round = "Debugging", explanation = "Cancellation helps but should not be the only guard. Model loading and errors per request, avoid sharing unrelated cache keys, and reproduce deliberately reversed response order.", code = "", mistake = "Assuming responses arrive in navigation order.", rubric = listOf("Use stable request identity", "Guard obsolete results", "Test reversed completion order"), followups = listOf("How does caching change the design?", "What should be shown during navigation?"), sourceIds = listOf("mdn-javascript"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "frontend-design-platform", area = "Frontend", level = 4, q = "Several frontend teams build incompatible controls. How would you improve the shared platform?", a = "Define accessible contracts and contribution ownership, then deliver reusable components with measured adoption and migration support.", subtopic = "Architecture", round = "Leadership", explanation = "Validate real product workflows and avoid forcing every exceptional interaction into one component. Establish versioning, compatibility checks, and an escalation path for product-specific needs.", code = "", mistake = "Equating shared code with consistent user behavior.", rubric = listOf("Define accessible contracts", "Validate product consumers", "Govern versions and exceptions"), followups = listOf("How do you prioritize requests?", "What signals a component should be split?"), sourceIds = listOf("w3c-accessibility", "react"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "frontend-multiapp", area = "Frontend", level = 4, q = "Would independently deployed frontend modules help a large organization?", a = "Compare team autonomy with integration, dependency, performance, and user-experience costs before choosing boundaries.", subtopic = "Architecture", round = "System design", explanation = "Define routing, authentication, shared design contracts, and failure containment. A modular monolith may meet the need with less operational cost. Pilot a boundary with objective delivery metrics.", code = "", mistake = "Adopting micro frontends solely because many teams exist.", rubric = listOf("Clarify organizational needs", "Define integration contracts", "Measure performance and delivery trade-offs"), followups = listOf("How do modules share authentication?", "What happens when one module fails?"), sourceIds = listOf("mdn-javascript", "sre-book"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview")
)
