    Q(id = "javascript-path-02", area = "JavaScript and TypeScript", level = 1, q = "Why prefer strict equality for most application comparisons?", a = "Strict equality avoids coercive conversion.", subtopic = "Equality", round = "Fundamentals", explanation = "Strict equality avoids coercive conversion. Coercion can surprise API boundary checks. Normalize inputs deliberately before comparison.", code = "", mistake = "Relying on truthiness for valid zero values.", rubric = listOf("Strict equality avoids coercive conversion", "Coercion can surprise API boundary checks", "Normalize inputs deliberately before comparison"), followups = listOf("How should you distinguish null from undefined?", "Walk through a concrete example of equality and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-03", area = "JavaScript and TypeScript", level = 1, q = "How can a closure keep data alive unexpectedly?", a = "A function retains referenced lexical bindings.", subtopic = "Closures", round = "Fundamentals", explanation = "A function retains referenced lexical bindings. Long-lived callbacks can retain objects. Remove subscriptions when ownership ends.", code = "", mistake = "Assuming local variables disappear after return.", rubric = listOf("A function retains referenced lexical bindings", "Long-lived callbacks can retain objects", "Remove subscriptions when ownership ends"), followups = listOf("How would you diagnose a listener memory leak?", "Walk through a concrete example of closures and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-04", area = "JavaScript and TypeScript", level = 1, q = "What happens when you spread an object containing nested objects?", a = "Spread copies enumerable own properties.", subtopic = "Objects", round = "Fundamentals", explanation = "Spread copies enumerable own properties. Nested object references remain shared. Clone only the depth required by ownership.", code = "", mistake = "Treating object spread as a deep clone.", rubric = listOf("Spread copies enumerable own properties", "Nested object references remain shared", "Clone only the depth required by ownership"), followups = listOf("What happens to prototype methods after spread?", "Walk through a concrete example of objects and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-05", area = "JavaScript and TypeScript", level = 1, q = "When should you use map rather than forEach?", a = "Map produces transformed results.", subtopic = "Arrays", round = "Fundamentals", explanation = "Map produces transformed results. ForEach is suited to side effects. Return values determine the new mapped array.", code = "", mistake = "Using map and discarding its result.", rubric = listOf("Map produces transformed results", "ForEach is suited to side effects", "Return values determine the new mapped array"), followups = listOf("How would you transform and filter a collection?", "Walk through a concrete example of arrays and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-06", area = "JavaScript and TypeScript", level = 1, q = "What is the difference between a returned promise and an unreturned one?", a = "Returning connects asynchronous completion.", subtopic = "Promises", round = "Fundamentals", explanation = "Returning connects asynchronous completion. A missing return breaks the chain. Propagate failures to the caller.", code = "", mistake = "Starting a promise without handling its rejection.", rubric = listOf("Returning connects asynchronous completion", "A missing return breaks the chain", "Propagate failures to the caller"), followups = listOf("How would you test chained failure propagation?", "Walk through a concrete example of promises and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-07", area = "JavaScript and TypeScript", level = 1, q = "Does a TypeScript interface validate JSON at runtime?", a = "Interfaces are erased during compilation.", subtopic = "Type checking", round = "Fundamentals", explanation = "Interfaces are erased during compilation. External input still needs runtime validation. Narrow validated data before use.", code = "", mistake = "Casting network JSON and assuming it is safe.", rubric = listOf("Interfaces are erased during compilation", "External input still needs runtime validation", "Narrow validated data before use"), followups = listOf("Where should schema validation occur?", "Walk through a concrete example of type checking and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-08", area = "JavaScript and TypeScript", level = 1, q = "How can a discriminated union replace optional fields?", a = "A tag identifies the active variant.", subtopic = "Union types", round = "Fundamentals", explanation = "A tag identifies the active variant. Each variant owns valid fields. Exhaustive checks catch missing cases.", code = "", mistake = "Allowing impossible combinations of optional properties.", rubric = listOf("A tag identifies the active variant", "Each variant owns valid fields", "Exhaustive checks catch missing cases"), followups = listOf("How would you model a payment result?", "Walk through a concrete example of union types and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-09", area = "JavaScript and TypeScript", level = 2, q = "Why can a long promise callback still freeze a UI?", a = "Callbacks run on the executing thread.", subtopic = "Event loop", round = "Scenario", explanation = "Callbacks run on the executing thread. Microtasks can delay later work. Break up or offload expensive computation.", code = "", mistake = "Assuming promise code is automatically parallel.", rubric = listOf("Callbacks run on the executing thread", "Microtasks can delay later work", "Break up or offload expensive computation"), followups = listOf("When would a worker help?", "Walk through a concrete example of event loop and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-10", area = "JavaScript and TypeScript", level = 2, q = "Why does await inside forEach not wait for every callback?", a = "ForEach ignores returned promises.", subtopic = "Async collections", round = "Scenario", explanation = "ForEach ignores returned promises. Use sequential iteration for ordering. Use Promise.all for bounded independent work.", code = "", mistake = "Expecting forEach to await asynchronous callbacks.", rubric = listOf("ForEach ignores returned promises", "Use sequential iteration for ordering", "Use Promise.all for bounded independent work"), followups = listOf("How would you cap parallel requests?", "Walk through a concrete example of async collections and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-11", area = "JavaScript and TypeScript", level = 2, q = "How should an asynchronous API preserve useful error context?", a = "Keep the original cause.", subtopic = "Errors", round = "Scenario", explanation = "Keep the original cause. Add operation context at boundaries. Avoid swallowing rejections silently.", code = "", mistake = "Replacing every error with a generic string.", rubric = listOf("Keep the original cause", "Add operation context at boundaries", "Avoid swallowing rejections silently"), followups = listOf("Which details must be redacted from logs?", "Walk through a concrete example of errors and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-12", area = "JavaScript and TypeScript", level = 2, q = "Why can an unchecked type assertion hide a real bug?", a = "Assertions only influence the compiler.", subtopic = "Narrowing", round = "Scenario", explanation = "Assertions only influence the compiler. They do not transform runtime values. Prefer guards for uncertain inputs.", code = "", mistake = "Using assertions to silence all compiler errors.", rubric = listOf("Assertions only influence the compiler", "They do not transform runtime values", "Prefer guards for uncertain inputs"), followups = listOf("How would you implement an unknown-value guard?", "Walk through a concrete example of narrowing and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-13", area = "JavaScript and TypeScript", level = 2, q = "How can a circular module dependency fail at initialization?", a = "Modules may observe uninitialized bindings.", subtopic = "Modules", round = "Scenario", explanation = "Modules may observe uninitialized bindings. Side effects depend on evaluation order. Move shared contracts into a separate module.", code = "", mistake = "Assuming import order always solves a cycle.", rubric = listOf("Modules may observe uninitialized bindings", "Side effects depend on evaluation order", "Move shared contracts into a separate module"), followups = listOf("How would you remove the cycle structurally?", "Walk through a concrete example of modules and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-14", area = "JavaScript and TypeScript", level = 2, q = "Why can JavaScript lose precision for a large database identifier?", a = "Numbers use floating-point representation.", subtopic = "Numbers", round = "Scenario", explanation = "Numbers use floating-point representation. Large integers may exceed safe precision. Use strings or BigInt under an explicit contract.", code = "", mistake = "Parsing every identifier as Number.", rubric = listOf("Numbers use floating-point representation", "Large integers may exceed safe precision", "Use strings or BigInt under an explicit contract"), followups = listOf("How does BigInt affect JSON serialization?", "Walk through a concrete example of numbers and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-15", area = "JavaScript and TypeScript", level = 2, q = "How would you cancel a stale browser request?", a = "Pass an AbortSignal to supported APIs.", subtopic = "Cancellation", round = "Scenario", explanation = "Pass an AbortSignal to supported APIs. Abort when the request loses ownership. Also guard stale result application.", code = "", mistake = "Assuming cancellation alone prevents every stale update.", rubric = listOf("Pass an AbortSignal to supported APIs", "Abort when the request loses ownership", "Also guard stale result application"), followups = listOf("How should the UI handle AbortError?", "Walk through a concrete example of cancellation and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-16", area = "JavaScript and TypeScript", level = 2, q = "How should you test code that depends on time and randomness?", a = "Inject clocks and random sources.", subtopic = "Testing", round = "Scenario", explanation = "Inject clocks and random sources. Use controlled fake timers where appropriate. Assert behavior rather than implementation order.", code = "", mistake = "Using real sleeps to test debouncing.", rubric = listOf("Inject clocks and random sources", "Use controlled fake timers where appropriate", "Assert behavior rather than implementation order"), followups = listOf("What happens when promises and timers interact?", "Walk through a concrete example of testing and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
