    Q(id = "javascript-path-18", area = "JavaScript and TypeScript", level = 3, q = "What protection does readonly provide across an API boundary?", a = "It restricts mutation through typed references.", subtopic = "Readonly types", round = "Debugging", explanation = "It restricts mutation through typed references. It does not freeze runtime objects. Choose copies when shared ownership requires isolation.", code = "", mistake = "Treating readonly as a runtime security boundary.", rubric = listOf("It restricts mutation through typed references", "It does not freeze runtime objects", "Choose copies when shared ownership requires isolation"), followups = listOf("How would you prevent nested mutations?", "Walk through a concrete example of readonly types and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-19", area = "JavaScript and TypeScript", level = 3, q = "How would you diagnose a slow JavaScript interaction?", a = "Capture a performance trace.", subtopic = "Performance", round = "Debugging", explanation = "Capture a performance trace. Separate computation layout and network costs. Fix the dominant bottleneck.", code = "", mistake = "Assuming bundle size explains every slow interaction.", rubric = listOf("Capture a performance trace", "Separate computation layout and network costs", "Fix the dominant bottleneck"), followups = listOf("Which measurement confirms your improvement?", "Walk through a concrete example of performance and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-20", area = "JavaScript and TypeScript", level = 3, q = "How can caches cause memory growth in a long-running JavaScript app?", a = "Strong references retain cache entries.", subtopic = "Memory", round = "Debugging", explanation = "Strong references retain cache entries. Bound size or expire entries. Observe retained objects over repeated workloads.", code = "", mistake = "Creating unbounded global maps.", rubric = listOf("Strong references retain cache entries", "Bound size or expire entries", "Observe retained objects over repeated workloads"), followups = listOf("When is WeakMap a suitable alternative?", "Walk through a concrete example of memory and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview")
