    Q(id = "javascript-path-21", area = "JavaScript and TypeScript", level = 3, q = "How would you version a TypeScript SDK used by multiple services?", a = "Publish explicit compatible contracts.", subtopic = "Contracts", round = "Debugging", explanation = "Publish explicit compatible contracts. Test runtime payloads against schemas. Treat breaking types and behavior as versioned changes.", code = "", mistake = "Assuming compilation guarantees cross-service compatibility.", rubric = listOf("Publish explicit compatible contracts", "Test runtime payloads against schemas", "Treat breaking types and behavior as versioned changes"), followups = listOf("How would you deprecate a response field?", "Walk through a concrete example of contracts and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-22", area = "JavaScript and TypeScript", level = 3, q = "How should code render user-provided text safely?", a = "Prefer text rendering over HTML injection.", subtopic = "Security", round = "Debugging", explanation = "Prefer text rendering over HTML injection. Validate and sanitize intentional rich markup. Keep security checks at trusted boundaries.", code = "", mistake = "Concatenating untrusted strings into HTML.", rubric = listOf("Prefer text rendering over HTML injection", "Validate and sanitize intentional rich markup", "Keep security checks at trusted boundaries"), followups = listOf("How would a content security policy help?", "Walk through a concrete example of security and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
