    Q(id = "javascript-path-24", area = "JavaScript and TypeScript", level = 3, q = "Why can different module formats break an otherwise typed package?", a = "Runtime loaders expect compatible formats.", subtopic = "Build output", round = "Debugging", explanation = "Runtime loaders expect compatible formats. Export maps control supported entry points. Test actual consumer environments.", code = "", mistake = "Publishing types without testing runtime imports.", rubric = listOf("Runtime loaders expect compatible formats", "Export maps control supported entry points", "Test actual consumer environments"), followups = listOf("How would you support ESM and legacy consumers?", "Walk through a concrete example of build output and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-25", area = "JavaScript and TypeScript", level = 4, q = "How would you assess a new JavaScript dependency for production?", a = "Review maintenance security and license.", subtopic = "Dependency strategy", round = "Design", explanation = "Review maintenance security and license. Measure runtime and bundle impact. Prefer a bounded replaceable integration.", code = "", mistake = "Choosing solely by download count.", rubric = listOf("Review maintenance security and license", "Measure runtime and bundle impact", "Prefer a bounded replaceable integration"), followups = listOf("How would you respond to a transitive vulnerability?", "Walk through a concrete example of dependency strategy and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "javascript-path-26", area = "JavaScript and TypeScript", level = 4, q = "How would you migrate a large JavaScript codebase to TypeScript?", a = "Introduce checks in incremental boundaries.", subtopic = "Migration", round = "Design", explanation = "Introduce checks in incremental boundaries. Prioritize shared contracts and risky inputs. Reduce escape hatches over time.", code = "", mistake = "Replacing every type error with any.", rubric = listOf("Introduce checks in incremental boundaries", "Prioritize shared contracts and risky inputs", "Reduce escape hatches over time"), followups = listOf("Which module would you migrate first?", "Walk through a concrete example of migration and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
