    Q(id = "javascript-path-30", area = "JavaScript and TypeScript", level = 4, q = "How would you keep a JavaScript client usable during partial outages?", a = "Set request deadlines and retry limits.", subtopic = "Reliability", round = "Design", explanation = "Set request deadlines and retry limits. Preserve meaningful cached state. Expose recoverable failure states.", code = "", mistake = "Hiding every failure behind an endless spinner.", rubric = listOf("Set request deadlines and retry limits", "Preserve meaningful cached state", "Expose recoverable failure states"), followups = listOf("Which operations must never be retried blindly?", "Walk through a concrete example of reliability and explain one trade-off."), sourceIds = listOf("mdn-javascript", "typescript"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
