private fun questionPack49(): List<Q> = listOf(
    Q(id = "javascript-equality", area = "JavaScript and TypeScript", level = 1, q = "Why does comparing two separately created objects with === return false?", a = "Objects compare by identity. Separate objects can contain equal fields while having different identities.", subtopic = "JavaScript basics", round = "Fundamentals", explanation = "Decide whether the business requirement is identity or value comparison. Compare relevant fields or use a documented deep comparison; JSON serialization is not a universal equality algorithm.", code = "", mistake = "Assuming === recursively compares object fields.", rubric = listOf("Distinguish identity and value", "Choose domain fields", "Explain deep-comparison limits"), followups = listOf("How do NaN and Object.is behave?", "What about nested mutable objects?"), sourceIds = listOf("mdn-javascript"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "javascript-closure", area = "JavaScript and TypeScript", level = 1, q = "A delayed callback reads a variable that has since changed. How does a closure explain this?", a = "A closure captures access to its lexical environment; it does not automatically freeze a copy of every value.", subtopic = "Closures", round = "Debugging", explanation = "Create a separate binding or explicit immutable snapshot when each callback needs a particular value. Trace creation and execution order to avoid explaining asynchronous code only by syntax.", code = "", mistake = "Treating all captured state as a creation-time snapshot.", rubric = listOf("Explain lexical scope", "Trace callback execution", "Choose binding or snapshot semantics"), followups = listOf("Why does let help in loops?", "How can a closure retain memory?"), sourceIds = listOf("mdn-javascript"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "javascript-unknown", area = "JavaScript and TypeScript", level = 2, q = "An API returns unknown JSON. How do you safely convert it to a typed domain object?", a = "Validate the runtime structure and narrow unknown with checks or a schema parser before using domain fields.", subtopic = "TypeScript boundaries", round = "Coding", explanation = "TypeScript types disappear at runtime. Validate required fields, enum values, and ranges, then produce a useful error. A type assertion only changes compiler assumptions.", code = "", mistake = "Using as User as though it validates server data.", rubric = listOf("Separate compile-time and runtime guarantees", "Validate boundary input", "Handle invalid data explicitly"), followups = listOf("How do you model partial responses?", "When would a discriminated union help?"), sourceIds = listOf("typescript"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "javascript-promises", area = "JavaScript and TypeScript", level = 2, q = "Why does await inside a loop make independent network requests slow?", a = "It can serialize requests. Run independent work concurrently while bounding concurrency and defining failure handling.", subtopic = "Async JavaScript", round = "Debugging", explanation = "Promise.all rejects when an input rejects, but does not cancel remaining operations automatically. Use appropriate cancellation and limits rather than firing thousands of requests at once.", code = "", mistake = "Claiming Promise.all cancels all work on the first rejection.", rubric = listOf("Identify dependency ordering", "Bound concurrency", "Define rejection and cancellation policy"), followups = listOf("When use allSettled?", "How do you enforce a request deadline?"), sourceIds = listOf("mdn-javascript"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "javascript-union", area = "JavaScript and TypeScript", level = 3, q = "Model a payment workflow so impossible combinations of state fields are harder to express.", a = "Use a discriminated union with state-specific fields and exhaustive handling instead of unrelated optional fields.", subtopic = "Type modeling", round = "System design", explanation = "For example, success requires a receipt while failure requires an error reason. Validate transitions at runtime too; types alone cannot make external events arrive in the correct order.", code = "", mistake = "Assuming a union replaces business transition validation.", rubric = listOf("Define state-specific data", "Check exhaustive handling", "Validate external transitions"), followups = listOf("How would you evolve the union?", "What should persisted old states do?"), sourceIds = listOf("typescript"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "javascript-event-loop", area = "JavaScript and TypeScript", level = 3, q = "A JavaScript page freezes despite using promises around a calculation. Why?", a = "Promise scheduling does not move CPU work off the main thread. Break up work or use a worker when suitable.", subtopic = "Performance", round = "Debugging", explanation = "Measure long tasks and transfer costs. Keep DOM changes on the main thread and design cancellation or stale-result handling for worker responses. Async syntax is not parallel execution.", code = "", mistake = "Wrapping expensive work in a promise and calling it nonblocking.", rubric = listOf("Identify CPU blocking", "Choose chunking or a worker", "Measure responsiveness"), followups = listOf("When is worker serialization expensive?", "How do you ignore an old result?"), sourceIds = listOf("mdn-javascript", "node-event-loop"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "javascript-migration", area = "JavaScript and TypeScript", level = 4, q = "How would you introduce TypeScript into a large JavaScript product?", a = "Start at high-risk boundaries, enable checks incrementally, and agree on a policy for unsafe escape hatches.", subtopic = "Platform evolution", round = "Leadership", explanation = "Protect public contracts and build performance. Track unchecked modules, runtime validation gaps, and defect trends. Owners should remove temporary any usage with explicit priorities.", code = "", mistake = "Counting typed lines while ignoring unchecked data boundaries.", rubric = listOf("Prioritize migration risk", "Define escape-hatch ownership", "Measure quality and build cost"), followups = listOf("How do you handle untyped dependencies?", "When should strictness increase?"), sourceIds = listOf("typescript"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "javascript-package-contract", area = "JavaScript and TypeScript", level = 4, q = "Several teams share a TypeScript SDK. How do you prevent a release from breaking consumers?", a = "Treat runtime behavior and exported types as contracts, verify representative consumers, and release changes with compatibility evidence.", subtopic = "Architecture", round = "System design", explanation = "Account for module formats, supported runtimes, and declaration changes. Use deprecation periods and migration examples; compiler success in the SDK alone does not prove consumer compatibility.", code = "", mistake = "Treating generated declarations as the entire compatibility contract.", rubric = listOf("Test runtime and type contracts", "Cover supported consumers", "Plan deprecation and release recovery"), followups = listOf("Can a type-only change be breaking?", "How do you test multiple compiler versions?"), sourceIds = listOf("typescript", "mdn-javascript"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview")
)
private fun questionPack50(): List<Q> = listOf(
    Q(id = "kotlin-company-dispatchers", area = "Kotlin", level = 1, q = "Which dispatcher would you use for a blocking database read, parsing a large JSON file, and updating the UI? How does withContext fit in?", a = "Dispatchers.IO for blocking I/O such as a file or blocking database read, Dispatchers.Default for CPU-heavy work such as parsing or sorting, and Dispatchers.Main for UI. withContext switches the current coroutine to another dispatcher for a block, suspends until it finishes and returns its result, so a suspend function can make itself safe to call from the main thread.", subtopic = "Coroutines", round = "Fundamentals", explanation = "IO has a larger thread pool because its threads spend most of their time waiting; Default is sized to CPU cores. Main-safe functions own their dispatcher switch, so callers do not need to know. Libraries such as Room and Retrofit already provide main-safe suspend functions, so wrapping them again is unnecessary.", code = "", mistake = "Running CPU-heavy parsing on Dispatchers.IO, or wrapping already main-safe library calls in withContext.", rubric = listOf("Matches IO, Default and Main to the right work", "Explains what withContext does and returns", "Describes main-safe functions", "Knows library suspend functions may already be main-safe"), followups = listOf("Why is the IO pool larger than the Default pool?", "How would you inject dispatchers so tests can control them?"), sourceIds = listOf("android-company-experiences", "kotlin-coroutines"), version = 1, reviewedAt = "2026-10-11", origin = "PrepDesk original; InterviewGo topic reference"),
    Q(id = "kotlin-company-val-var", area = "Kotlin", level = 1, q = "Does declaring a property with val make the object it refers to immutable?", a = "No. val means the reference cannot be reassigned, while var can be. The object may still be mutable: a val of type MutableList can still be changed, and a val with a custom getter can return a different value on each read. Real immutability comes from read-only types holding immutable data, such as data classes with only val properties.", subtopic = "Variables", round = "Fundamentals", explanation = "Prefer val by default because it removes one source of change. Exposing a read-only List type over a mutable list still lets the owner change it underneath callers, so copy or use immutable collections when that matters.", code = "", mistake = "Assuming a val collection or object can never change.", rubric = listOf("Distinguishes reference reassignment from object mutation", "Gives a mutable-object example", "Mentions custom getters", "Explains how to achieve real immutability"), followups = listOf("What is the difference between val and const val?", "How would you expose a list safely from a class?"), sourceIds = listOf("android-company-experiences", "kotlin-language"), version = 1, reviewedAt = "2026-10-11", origin = "PrepDesk original; InterviewGo topic reference"),
    Q(id = "kotlin-company-launch-async", area = "Kotlin", level = 2, q = "How do launch and async differ, including how they report failures?", a = "launch starts work that returns no result and gives you a Job; async returns a Deferred whose value you read with await(). With structured concurrency, a failure in either cancels the parent scope unless it is supervised. async also rethrows the exception from await(), and under a SupervisorJob a failed async that nobody awaits can go unnoticed.", subtopic = "Coroutines", round = "Fundamentals", explanation = "Use async only for concurrent results you will await, typically inside coroutineScope so all children finish or fail together. A CoroutineExceptionHandler applies to launch-based root coroutines, not to async, whose errors surface at await().", code = "", mistake = "Using async for fire-and-forget work and never calling await, which hides failures.", rubric = listOf("Explains Job versus Deferred", "Describes failure propagation to the parent", "Notes that await rethrows", "Uses async only when results are awaited"), followups = listOf("How would you load two results concurrently but tolerate one failing?", "Where does a CoroutineExceptionHandler take effect?"), sourceIds = listOf("android-company-experiences", "kotlin-coroutines"), version = 1, reviewedAt = "2026-10-11", origin = "PrepDesk original; InterviewGo topic reference"),
    Q(id = "kotlin-company-companion", area = "Kotlin", level = 1, q = "What is a companion object, and how does it differ from Java static members?", a = "A companion object is a singleton object declared inside a class; you call its members through the class name. Unlike static members it is a real object: it can implement interfaces, be passed around, and have extensions. Use it for factory functions and constants, adding @JvmStatic or @JvmField only when Java callers need true statics.", subtopic = "Classes", round = "Fundamentals", explanation = "Because it is an object, a companion can satisfy an interface such as a factory contract. Top-level functions and properties are often simpler when nothing ties them to the class. const val is for compile-time primitives and strings.", code = "", mistake = "Moving every helper into a companion object out of Java habit when a top-level function would do.", rubric = listOf("Defines a companion as an object inside a class", "Contrasts it with Java static members", "Gives appropriate uses", "Mentions Java interop annotations"), followups = listOf("When would you prefer a top-level function?", "Can a companion object implement an interface? Why might that help?"), sourceIds = listOf("android-company-experiences", "kotlin-language"), version = 1, reviewedAt = "2026-10-11", origin = "PrepDesk original; InterviewGo topic reference"),
    Q(id = "kotlin-company-coroutines-threads", area = "Kotlin", level = 1, q = "Why can a program start 100,000 coroutines but not 100,000 threads?", a = "Coroutines are lightweight: a suspended coroutine is a small object storing where to resume, not an operating-system thread with its own stack. Many coroutines share a small pool of dispatcher threads and release the thread whenever they suspend. Blocking calls still hold the underlying thread, so they must run on a suitable dispatcher.", subtopic = "Coroutines", round = "Fundamentals", explanation = "The compiler turns suspend functions into state machines with continuations, so waiting costs memory for that state rather than a parked thread. The benefit disappears if code blocks inside a coroutine, because then each one does occupy a thread.", code = "", mistake = "Assuming coroutines make blocking code non-blocking or run in parallel automatically.", rubric = listOf("Explains suspension instead of blocking", "Contrasts coroutine memory with thread stacks", "Mentions sharing a dispatcher thread pool", "Warns about blocking calls"), followups = listOf("What is a continuation?", "What happens if 1,000 coroutines call Thread.sleep on Dispatchers.Default?"), sourceIds = listOf("android-company-experiences", "kotlin-coroutines"), version = 1, reviewedAt = "2026-10-11", origin = "PrepDesk original; InterviewGo topic reference")
)
private fun questionPack51(): List<Q> = listOf(
    Q(id = "kotlin-path-01", area = "Kotlin", level = 1, q = "How do safe calls and the Elvis operator work together?", a = "Safe calls propagate null.", subtopic = "Null safety", round = "Fundamentals", explanation = "Safe calls propagate null. Elvis supplies a fallback. Keep absence distinct from invalid data.", code = "", mistake = "Using non-null assertions everywhere.", rubric = listOf("Safe calls propagate null", "Elvis supplies a fallback", "Keep absence distinct from invalid data"), followups = listOf("When should a missing value become an error?", "Walk through a concrete example of null safety and explain one trade-off."), sourceIds = listOf("kotlin-language", "kotlin-coroutines"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
