    Q(id = "react-path-25", area = "React", level = 4, q = "How should a growing React app separate responsibilities?", a = "Keep domain rules testable independently.", subtopic = "Architecture", round = "Design", explanation = "Keep domain rules testable independently. Group features with clear boundaries. Centralize shared contracts carefully.", code = "", mistake = "Creating universal components before understanding use cases.", rubric = listOf("Keep domain rules testable independently", "Group features with clear boundaries", "Centralize shared contracts carefully"), followups = listOf("Which state belongs at a feature boundary?", "Walk through a concrete example of architecture and explain one trade-off."), sourceIds = listOf("react", "react-effects", "w3c-accessibility"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "react-path-26", area = "React", level = 4, q = "How would you evolve shared components without breaking products?", a = "Publish explicit interaction contracts.", subtopic = "Design systems", round = "Design", explanation = "Publish explicit interaction contracts. Test accessibility and visual states. Provide staged migration paths.", code = "", mistake = "Changing behavior through undocumented styling overrides.", rubric = listOf("Publish explicit interaction contracts", "Test accessibility and visual states", "Provide staged migration paths"), followups = listOf("How would you deprecate an old component?", "Walk through a concrete example of design systems and explain one trade-off."), sourceIds = listOf("react", "react-effects", "w3c-accessibility"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "react-path-27", area = "React", level = 4, q = "How should React applications handle intentionally rendered HTML?", a = "Treat supplied markup as untrusted.", subtopic = "Security", round = "Design", explanation = "Treat supplied markup as untrusted. Sanitize with an appropriate policy. Review allowed links and embeds.", code = "", mistake = "Assuming framework escaping covers raw HTML APIs.", rubric = listOf("Treat supplied markup as untrusted", "Sanitize with an appropriate policy", "Review allowed links and embeds"), followups = listOf("How would you test a malicious payload?", "Walk through a concrete example of security and explain one trade-off."), sourceIds = listOf("react", "react-effects", "w3c-accessibility"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "react-path-28", area = "React", level = 4, q = "How would you investigate a release that slows navigation?", a = "Compare production performance traces.", subtopic = "Delivery", round = "Design", explanation = "Compare production performance traces. Inspect route chunks and data waterfalls. Rollback or isolate the dominant regression.", code = "", mistake = "Optimizing only development-mode rendering.", rubric = listOf("Compare production performance traces", "Inspect route chunks and data waterfalls", "Rollback or isolate the dominant regression"), followups = listOf("Which user metric validates recovery?", "Walk through a concrete example of delivery and explain one trade-off."), sourceIds = listOf("react", "react-effects", "w3c-accessibility"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "react-path-29", area = "React", level = 4, q = "When are independently deployed frontend modules justified?", a = "Independent ownership can support deployment autonomy.", subtopic = "Microfrontends", round = "Design", explanation = "Independent ownership can support deployment autonomy. Shared runtime contracts add complexity. Compare costs against a modular application.", code = "", mistake = "Choosing microfrontends solely because teams grew.", rubric = listOf("Independent ownership can support deployment autonomy", "Shared runtime contracts add complexity", "Compare costs against a modular application"), followups = listOf("Who owns shared authentication behavior?", "Walk through a concrete example of microfrontends and explain one trade-off."), sourceIds = listOf("react", "react-effects", "w3c-accessibility"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "react-path-30", area = "React", level = 4, q = "What telemetry helps diagnose React UI failures?", a = "Record route and release context.", subtopic = "Observability", round = "Design", explanation = "Record route and release context. Capture errors with sensitive values redacted. Measure affected user journeys.", code = "", mistake = "Sending full component state to telemetry.", rubric = listOf("Record route and release context", "Capture errors with sensitive values redacted", "Measure affected user journeys"), followups = listOf("How would you correlate a UI failure with an API request?", "Walk through a concrete example of observability and explain one trade-off."), sourceIds = listOf("react", "react-effects", "w3c-accessibility"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "react-path-31", area = "React", level = 4, q = "How would you upgrade React across many applications?", a = "Check framework and dependency compatibility.", subtopic = "Upgrade strategy", round = "Design", explanation = "Check framework and dependency compatibility. Run focused interaction and hydration tests. Roll out by risk and monitor results.", code = "", mistake = "Upgrading only the core package version.", rubric = listOf("Check framework and dependency compatibility", "Run focused interaction and hydration tests", "Roll out by risk and monitor results"), followups = listOf("How would you test third-party component compatibility?", "Walk through a concrete example of upgrade strategy and explain one trade-off."), sourceIds = listOf("react", "react-effects", "w3c-accessibility"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "react-path-32", area = "React", level = 4, q = "How should a React product work under unstable connectivity?", a = "Preserve user drafts locally where appropriate.", subtopic = "Product resilience", round = "Design", explanation = "Preserve user drafts locally where appropriate. Show stale and pending states clearly. Retry safely within explicit limits.", code = "", mistake = "Disabling the whole interface after one failed request.", rubric = listOf("Preserve user drafts locally where appropriate", "Show stale and pending states clearly", "Retry safely within explicit limits"), followups = listOf("How would reconnect reconcile pending edits?", "Walk through a concrete example of product resilience and explain one trade-off."), sourceIds = listOf("react", "react-effects", "w3c-accessibility"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview")
