private fun questionPack71(): List<Q> = listOf(
    Q(id = "react-state", area = "React", level = 1, q = "Why can a React handler read the old count just after calling its setter?", a = "State belongs to a render snapshot. Setting state schedules a later render rather than mutating the current handler snapshot.", subtopic = "State", round = "Fundamentals", explanation = "Use an updater when the next value depends on previous state. Avoid assuming the setter returns a completion promise. Explain which render created the handler.", code = "", mistake = "Expecting the local count variable to change immediately.", rubric = listOf("Explain render snapshots", "Use a functional updater", "Avoid relying on synchronous mutation"), followups = listOf("Why can repeated count+1 updates collapse?", "When would a ref be useful?"), sourceIds = listOf("react"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "react-keys", area = "React", level = 1, q = "After reordering a list, input text appears in the wrong row. What should you check?", a = "Use stable item identity for keys. Position-based keys can associate existing component state with another item.", subtopic = "Lists", round = "Debugging", explanation = "Keys only need uniqueness among siblings. Define identity in the data model and test insertions, deletions, and reorder operations with stateful rows.", code = "", mistake = "Generating a fresh random key on every render.", rubric = listOf("Explain identity during reconciliation", "Choose stable data keys", "Test stateful reorder cases"), followups = listOf("When is an index acceptable?", "What does changing a key intentionally do?"), sourceIds = listOf("react"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "react-effects", area = "React", level = 2, q = "An effect opens two subscriptions during development. How should it be written?", a = "An effect should have cleanup that reverses setup. Development checks can exercise setup, cleanup, and setup to reveal leaks.", subtopic = "Effects", round = "Debugging", explanation = "Use correct dependencies and unsubscribe from the exact resource created by the effect. Do not hide a leak with a run-once flag. Confirm production and development behavior separately.", code = "", mistake = "Disabling development checks to conceal missing cleanup.", rubric = listOf("Pair setup with cleanup", "Use correct dependencies", "Verify repeated mount behavior"), followups = listOf("When does cleanup run?", "Should derived state use an effect?"), sourceIds = listOf("react-effects"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "react-search", area = "React", level = 2, q = "A slow old search response replaces newer results. How would you prevent this?", a = "Cancel obsolete requests when possible and ensure only the current request can update visible results.", subtopic = "Async UI", round = "Coding", explanation = "Use request identity or an ignore flag tied to effect cleanup, plus loading and error states. Debouncing reduces traffic but does not by itself prevent out-of-order results.", code = "", mistake = "Assuming a debounce guarantees correct response ordering.", rubric = listOf("Guard response identity", "Clean up obsolete work", "Test reversed response order"), followups = listOf("How should empty search behave?", "What if cancellation is unavailable?"), sourceIds = listOf("react-effects"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "react-state-ownership", area = "React", level = 3, q = "An editor has local selection, server documents, and shared undo history. Where should state live?", a = "Keep each state at the smallest appropriate owner, separate server cache from editable drafts, and define who owns undo history.", subtopic = "Architecture", round = "System design", explanation = "Avoid duplicating derived values and copying remote data into several stores. Define save conflicts, invalidation, and reset behavior before choosing a state library.", code = "", mistake = "Choosing a global store before defining ownership.", rubric = listOf("Separate state lifetimes", "Define a source of truth", "Handle save and reset conflicts"), followups = listOf("What survives navigation?", "How would offline edits merge?"), sourceIds = listOf("react"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "react-performance", area = "React", level = 3, q = "A dashboard rerenders often. Should every component be memoized?", a = "Profile the interaction first, then reduce expensive work and unstable inputs where measurements justify it.", subtopic = "Performance", round = "Debugging", explanation = "A rerender is not automatically a slow interaction. Move state closer to its users, avoid unnecessary effects, and evaluate list virtualization. Memoization has comparison and maintenance costs.", code = "", mistake = "Using memoization without a measured bottleneck.", rubric = listOf("Profile user-visible latency", "Inspect state and prop stability", "Validate the change"), followups = listOf("When can a memo still rerender?", "How do you benchmark a long list?"), sourceIds = listOf("react"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "react-design-system", area = "React", level = 4, q = "How would you govern a React design system used by many teams?", a = "Define accessible component contracts, versioning, ownership, and a contribution process with consumer validation.", subtopic = "Architecture", round = "Leadership", explanation = "Test keyboard and screen-reader behavior alongside visuals. Support migration paths, avoid leaking implementation details into contracts, and track adoption and repeated product defects.", code = "", mistake = "Treating visual consistency as sufficient accessibility.", rubric = listOf("Define stable accessible contracts", "Validate real consumers", "Plan versioning and migration"), followups = listOf("Who approves a breaking change?", "How do teams request an exception?"), sourceIds = listOf("react", "w3c-accessibility"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "react-render-strategy", area = "React", level = 4, q = "Choose client rendering versus server-assisted rendering for a React storefront.", a = "Compare first-load behavior, indexing needs, personalization, cacheability, infrastructure cost, and interactive complexity.", subtopic = "Architecture", round = "System design", explanation = "Map which data can be public or user-specific. Plan loading boundaries, failure states, and consistent initial UI. Validate on slow devices and networks instead of choosing by trend.", code = "", mistake = "Caching personalized responses as though they were public pages.", rubric = listOf("Map rendering requirements", "Separate public and private data", "Measure end-user performance"), followups = listOf("What causes hydration mismatches?", "How do you handle stale prices?"), sourceIds = listOf("react", "http-caching"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview")
)
