    Q(id = "rust-path-01", area = "Rust", level = 1, q = "Why does moving a String invalidate the old binding?", a = "Owned data has a responsible owner.", subtopic = "Ownership", round = "Fundamentals", explanation = "Owned data has a responsible owner. A move transfers that responsibility. Use borrowing for temporary access.", code = "", mistake = "Assuming every assignment copies heap data.", rubric = listOf("Owned data has a responsible owner", "A move transfers that responsibility", "Use borrowing for temporary access"), followups = listOf("How does a Copy type behave differently?", "Walk through a concrete example of ownership and explain one trade-off."), sourceIds = listOf("rust-book"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "rust-path-02", area = "Rust", level = 1, q = "What rule prevents competing mutable access?", a = "A mutable borrow requires exclusive access.", subtopic = "Borrowing", round = "Fundamentals", explanation = "A mutable borrow requires exclusive access. Shared borrows allow reading. Lifetimes bound overlapping usage.", code = "", mistake = "Keeping shared references while mutating the same value.", rubric = listOf("A mutable borrow requires exclusive access", "Shared borrows allow reading", "Lifetimes bound overlapping usage"), followups = listOf("How does non-lexical lifetime analysis help?", "Walk through a concrete example of borrowing and explain one trade-off."), sourceIds = listOf("rust-book"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
