    Q(id = "rust-path-05", area = "Rust", level = 1, q = "Why does Option make absence explicit?", a = "Some carries a value.", subtopic = "Options", round = "Fundamentals", explanation = "Some carries a value. None represents no value. Callers must handle or propagate absence.", code = "", mistake = "Unwrapping every optional value blindly.", rubric = listOf("Some carries a value", "None represents no value", "Callers must handle or propagate absence"), followups = listOf("When should absence become an error?", "Walk through a concrete example of options and explain one trade-off."), sourceIds = listOf("rust-book"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "rust-path-06", area = "Rust", level = 1, q = "How does the question-mark operator handle errors?", a = "It propagates compatible failures.", subtopic = "Results", round = "Fundamentals", explanation = "It propagates compatible failures. Successful values continue evaluation. Conversion must satisfy required error contracts.", code = "", mistake = "Expecting it to ignore errors.", rubric = listOf("It propagates compatible failures", "Successful values continue evaluation", "Conversion must satisfy required error contracts"), followups = listOf("How would you add useful error context?", "Walk through a concrete example of results and explain one trade-off."), sourceIds = listOf("rust-book"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "rust-path-07", area = "Rust", level = 1, q = "What does a trait express?", a = "It defines shared behavior.", subtopic = "Traits", round = "Fundamentals", explanation = "It defines shared behavior. Implementations provide concrete operations. Bounds describe required capabilities.", code = "", mistake = "Using inheritance assumptions for trait composition.", rubric = listOf("It defines shared behavior", "Implementations provide concrete operations", "Bounds describe required capabilities"), followups = listOf("When would a default method help?", "Walk through a concrete example of traits and explain one trade-off."), sourceIds = listOf("rust-book"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "rust-path-08", area = "Rust", level = 1, q = "Why can a vector push invalidate a reference to an element?", a = "Growth may reallocate storage.", subtopic = "Collections", round = "Fundamentals", explanation = "Growth may reallocate storage. References must remain valid. Borrow rules prevent unsafe overlapping mutation.", code = "", mistake = "Keeping element references while extending the vector.", rubric = listOf("Growth may reallocate storage", "References must remain valid", "Borrow rules prevent unsafe overlapping mutation"), followups = listOf("How would indexes differ from references?", "Walk through a concrete example of collections and explain one trade-off."), sourceIds = listOf("rust-book"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "rust-path-09", area = "Rust", level = 2, q = "What do explicit lifetime parameters describe?", a = "They relate reference validity.", subtopic = "Lifetimes", round = "Scenario", explanation = "They relate reference validity. They do not extend object lifetime. Return references must originate from valid storage.", code = "", mistake = "Using annotations to rescue a reference to a local value.", rubric = listOf("They relate reference validity", "They do not extend object lifetime", "Return references must originate from valid storage"), followups = listOf("How would you return owned data instead?", "Walk through a concrete example of lifetimes and explain one trade-off."), sourceIds = listOf("rust-book"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "rust-path-10", area = "Rust", level = 2, q = "When are iterator adapters evaluated?", a = "Adapters are generally lazy.", subtopic = "Iterators", round = "Scenario", explanation = "Adapters are generally lazy. Consumption drives iteration. Collect materializes output into a chosen collection.", code = "", mistake = "Expecting map alone to execute side effects.", rubric = listOf("Adapters are generally lazy", "Consumption drives iteration", "Collect materializes output into a chosen collection"), followups = listOf("How would you stop at the first match?", "Walk through a concrete example of iterators and explain one trade-off."), sourceIds = listOf("rust-book"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "rust-path-11", area = "Rust", level = 2, q = "When is clone a poor response to a borrow-checker error?", a = "Cloning can copy substantial data.", subtopic = "Cloning", round = "Scenario", explanation = "Cloning can copy substantial data. It may hide unclear ownership. Redesign lifetimes or boundaries when appropriate.", code = "", mistake = "Cloning everything until compilation succeeds.", rubric = listOf("Cloning can copy substantial data", "It may hide unclear ownership", "Redesign lifetimes or boundaries when appropriate"), followups = listOf("When would an intentional clone be correct?", "Walk through a concrete example of cloning and explain one trade-off."), sourceIds = listOf("rust-book"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "rust-path-12", area = "Rust", level = 2, q = "Why is exhaustive matching useful for API evolution?", a = "It exposes unhandled variants.", subtopic = "Pattern matching", round = "Scenario", explanation = "It exposes unhandled variants. Variant data narrows safely. Wildcard handling may hide meaningful changes.", code = "", mistake = "Using a wildcard for every domain error.", rubric = listOf("It exposes unhandled variants", "Variant data narrows safely", "Wildcard handling may hide meaningful changes"), followups = listOf("How would a new variant affect consumers?", "Walk through a concrete example of pattern matching and explain one trade-off."), sourceIds = listOf("rust-book"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "rust-path-13", area = "Rust", level = 2, q = "How should visibility guide Rust module design?", a = "Keep implementation details private.", subtopic = "Modules", round = "Scenario", explanation = "Keep implementation details private. Expose focused public contracts. Re-export intentional entry points.", code = "", mistake = "Making every item public for convenience.", rubric = listOf("Keep implementation details private", "Expose focused public contracts", "Re-export intentional entry points"), followups = listOf("What does crate-level visibility permit?", "Walk through a concrete example of modules and explain one trade-off."), sourceIds = listOf("rust-book"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
