    Q(id = "rust-path-15", area = "Rust", level = 2, q = "How does Drop support resource management?", a = "Destruction follows ownership lifetime.", subtopic = "Resources", round = "Scenario", explanation = "Destruction follows ownership lifetime. Owned wrappers can release resources. Avoid relying on panics for normal errors.", code = "", mistake = "Using process termination as routine cleanup.", rubric = listOf("Destruction follows ownership lifetime", "Owned wrappers can release resources", "Avoid relying on panics for normal errors"), followups = listOf("How would an early return affect cleanup?", "Walk through a concrete example of resources and explain one trade-off."), sourceIds = listOf("rust-book"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
    Q(id = "rust-path-16", area = "Rust", level = 2, q = "When should a Rust library define a custom error type?", a = "Expose meaningful failure variants.", subtopic = "Error models", round = "Scenario", explanation = "Expose meaningful failure variants. Preserve causes for diagnosis. Keep callers able to classify failures.", code = "", mistake = "Returning only opaque strings from every API.", rubric = listOf("Expose meaningful failure variants", "Preserve causes for diagnosis", "Keep callers able to classify failures"), followups = listOf("How would a caller identify a transient error?", "Walk through a concrete example of error models and explain one trade-off."), sourceIds = listOf("rust-book"), version = 1, reviewedAt = "2026-10-09", origin = "PrepDesk original; linked documentation is further reading, not a claim of an actual company interview"),
