    Q(id = "security-injection", area = "Security", level = 1, q = "Why is concatenating user input into SQL dangerous?", a = "Input can become executable SQL syntax. Use parameterized queries and keep identifiers or query structure under deliberate control.", subtopic = "Input boundaries", round = "Debugging", explanation = "Parameters bind values, not arbitrary table names or sort expressions. Allowlist structural choices and restrict database permissions. Escaping manually is fragile and database-specific.", code = "", mistake = "Assuming value parameters can safely replace any SQL fragment.", rubric = listOf("Separate code and data", "Bind values safely", "Allowlist structural choices"), followups = listOf("How do you handle user-selected sorting?", "Does an ORM eliminate every injection risk?"), sourceIds = listOf("owasp-testing"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "security-object-access", area = "Security", level = 2, q = "Design a secure endpoint for changing a user profile.", a = "Authenticate the caller, authorize the target profile, and allow only fields that caller may change.", subtopic = "API security", round = "Coding", explanation = "Validate field types and ranges and avoid binding all JSON into internal models. Test changing roles, tenant IDs, and hidden properties. Log decisions without storing sensitive tokens.", code = "", mistake = "Allowing mass assignment of all submitted fields.", rubric = listOf("Enforce object permissions", "Allowlist editable fields", "Test privilege-changing input"), followups = listOf("How should an admin endpoint differ?", "What should an audit record contain?"), sourceIds = listOf("owasp-api"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
