    Q(id = "security-threat-model", area = "Security", level = 3, q = "Threat-model a file upload service.", a = "Map actors, trust boundaries, storage and processing paths, then address authorization, resource abuse, unsafe content handling, and data exposure.", subtopic = "Threat modeling", round = "System design", explanation = "Enforce size and processing limits, isolate parsers, and avoid serving active content from a trusted application origin. Validate download permissions and lifecycle deletion too.", code = "", mistake = "Checking only a filename extension and declaring uploads safe.", rubric = listOf("Map boundaries and abuse cases", "Bound and isolate processing", "Protect storage and download access"), followups = listOf("How do you handle decompression bombs?", "What if content is scanned asynchronously?"), sourceIds = listOf("owasp-api", "owasp-testing"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "security-abuse", area = "Security", level = 3, q = "An authenticated API is overwhelmed by expensive legitimate-looking requests. What controls help?", a = "Apply per-identity and workload-aware limits, bound resource usage, and detect abusive patterns with meaningful telemetry.", subtopic = "Resource protection", round = "Debugging", explanation = "Authentication alone does not limit cost. Cap query complexity, result size, concurrency, and downstream fan-out. Choose denial behavior that protects availability without leaking sensitive internals.", code = "", mistake = "Using only an IP request counter for every kind of workload.", rubric = listOf("Measure per-request cost", "Bound expensive operations", "Use identity-aware abuse controls"), followups = listOf("How do shared IPs affect limits?", "What if attackers create many accounts?"), sourceIds = listOf("owasp-api", "sre-overload"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "security-program", area = "Security", level = 4, q = "Create a security improvement program for a fast-growing engineering organization.", a = "Prioritize demonstrated risks, assign remediation owners, and integrate review and automated checks into normal delivery.", subtopic = "Security strategy", round = "Leadership", explanation = "Provide secure defaults and practical guidance. Track repeated defect classes, remediation time, and exception expiry. Security checklists need evidence from the actual system and its threats.", code = "", mistake = "Measuring success only by the number of scanner findings.", rubric = listOf("Prioritize business and technical risks", "Assign accountable owners", "Measure prevention and remediation"), followups = listOf("How do you handle accepted risk?", "Which controls should become platform defaults?"), sourceIds = listOf("owasp-api", "owasp-testing"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
