private fun questionPack80(): List<Q> = listOf(
    Q(id = "swift-optionals", area = "iOS and Swift", level = 1, q = "How should a Swift app handle a missing value from an API?", a = "Model absence with an optional or explicit result, then unwrap deliberately with a suitable fallback or error path.", subtopic = "Swift basics", round = "Fundamentals", explanation = "Force-unwrapping asserts that the value exists and can trap when it does not. Decide whether missing data is valid, recoverable, or a contract violation and test each case.", code = "", mistake = "Using force unwrap for every parsed API field.", rubric = listOf("Model absence explicitly", "Choose safe unwrapping", "Test missing and invalid values"), followups = listOf("When is guard let useful?", "How does optional chaining behave?"), sourceIds = listOf("swift-language"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "swift-retain-cycle", area = "iOS and Swift", level = 1, q = "A view controller stays alive after dismissal. What ownership issue might cause it?", a = "A strong reference cycle may involve stored closures or delegates. Inspect ownership and use weak references where lifetime requires them.", subtopic = "Memory", round = "Debugging", explanation = "ARC releases objects when strong ownership disappears. A weak reference can become nil; unowned requires a stronger lifetime guarantee. Avoid weakening references blindly without understanding needed ownership.", code = "", mistake = "Using unowned solely to avoid handling nil.", rubric = listOf("Trace strong ownership", "Break the actual cycle", "Distinguish weak and unowned"), followups = listOf("Can a closure capture self strongly safely?", "How would you verify deallocation?"), sourceIds = listOf("swift-language"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "swift-mainactor", area = "iOS and Swift", level = 2, q = "A background fetch updates SwiftUI state. How should you define the UI boundary?", a = "Isolate UI state to the main actor and cross that boundary explicitly when publishing results.", subtopic = "Concurrency", round = "Coding", explanation = "Actor isolation concerns access safety, while async describes suspension. Avoid doing heavy synchronous computation on the main actor and handle stale results and cancellation.", code = "", mistake = "Assuming every async method runs away from UI execution.", rubric = listOf("Isolate UI mutations", "Keep heavy work off UI execution", "Handle cancellation and stale results"), followups = listOf("Does await always change threads?", "How should errors reach the view?"), sourceIds = listOf("swift-concurrency", "swiftui-data"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "swift-state", area = "iOS and Swift", level = 2, q = "A SwiftUI screen repeatedly recreates its model or loses edits. What do you inspect?", a = "Check model ownership, view identity, and the observation/state mechanism appropriate to the app deployment target.", subtopic = "SwiftUI state", round = "Debugging", explanation = "Views are frequently rebuilt value descriptions. The model lifetime must belong to a stable owner, and drafts should not reset whenever remote data is refreshed. Verify navigation and identity changes.", code = "", mistake = "Treating every view initialization as a new user session.", rubric = listOf("Define stable model ownership", "Inspect view identity", "Preserve draft lifetime intentionally"), followups = listOf("What should reset on sign-out?", "How does a list identity change affect state?"), sourceIds = listOf("swiftui-data"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "swift-reentrancy", area = "iOS and Swift", level = 3, q = "An actor validates balance, awaits another service, and later writes balance. Why might it still be wrong?", a = "Actor isolation prevents simultaneous unsafe access, but another task can change actor state while the method is suspended.", subtopic = "Actors", round = "Debugging", explanation = "Revalidate assumptions after await or restructure the invariant so critical updates happen without suspension. External side effects need idempotency and reconciliation beyond local actor isolation.", code = "", mistake = "Assuming an actor method is atomic across every await.", rubric = listOf("Explain suspension and reentrancy", "Revalidate business invariants", "Handle external side effects"), followups = listOf("What if two reservations interleave?", "When should work be split into phases?"), sourceIds = listOf("swift-concurrency"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "swift-offline", area = "iOS and Swift", level = 3, q = "Design an iOS notes app that works offline and syncs later.", a = "Use a local source of truth with durable pending operations, stable note IDs, and an explicit conflict policy.", subtopic = "App architecture", round = "System design", explanation = "Separate rendering from synchronization and account for background execution limits. Test interrupted saves and retries. Decide whether conflicts are merged, duplicated, or shown to the user.", code = "", mistake = "Assuming background work will run at a precise time.", rubric = listOf("Persist local edits and pending work", "Define conflict resolution", "Test interruption and retries"), followups = listOf("How do you represent deletions?", "What if two devices edit the same note?"), sourceIds = listOf("swiftui-data", "android-architecture"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "swift-module", area = "iOS and Swift", level = 4, q = "How would you modularize a large iOS app without slowing delivery?", a = "Create boundaries around capabilities and stable contracts, then measure build, runtime, and coordination costs.", subtopic = "Architecture", round = "System design", explanation = "Define navigation, state ownership, and dependency rules. Move incrementally with compatibility checks and clear owners. Module count alone is not evidence of better architecture.", code = "", mistake = "Splitting files into packages without changing dependency direction.", rubric = listOf("Define capability and contract boundaries", "Assign ownership", "Measure build and delivery outcomes"), followups = listOf("How should modules share design components?", "What belongs in a shared core?"), sourceIds = listOf("swift-language", "swiftui-data"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "swift-concurrency-migration", area = "iOS and Swift", level = 4, q = "Plan adoption of stricter Swift concurrency checking in a mature app.", a = "Inventory isolation violations and foreign APIs, establish actor and Sendable rules, and migrate in reviewed increments.", subtopic = "Platform evolution", round = "Leadership", explanation = "Do not silence diagnostics globally. Bridge callbacks with cancellation and lifetime guarantees, test UI behavior, and document justified exceptions. Supported platform/toolchain combinations need explicit validation.", code = "", mistake = "Suppressing every concurrency warning without reviewing ownership.", rubric = listOf("Map isolation boundaries", "Validate callback bridges", "Govern exceptions and rollout"), followups = listOf("How do you handle non-Sendable legacy objects?", "Which module would you migrate first?"), sourceIds = listOf("swift-concurrency"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview")
