    Q(id = "system-design-rate-limit", area = "System Design", level = 2, q = "Design a per-user API rate limiter. What should happen across multiple instances?", a = "Define the rate window and burst allowance, then coordinate counts or tokens according to the required precision and failure policy.", subtopic = "Traffic control", round = "Coding", explanation = "A process-local limiter only sees local traffic. Account for tenant identity, trusted proxies, clock behavior, and limiter-store outages. Report limits predictably and avoid exposing sensitive state.", code = "", mistake = "Claiming a local map enforces a strict global limit.", rubric = listOf("Define window and burst semantics", "Coordinate distributed state", "Choose outage behavior"), followups = listOf("When can approximate limits be acceptable?", "How do you avoid limiting by a forged identity?"), sourceIds = listOf("sre-overload", "http-semantics"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "system-design-orders", area = "System Design", level = 3, q = "Design order placement with inventory and payment services.", a = "State business invariants, coordinate steps with durable workflow state, and define compensation and reconciliation.", subtopic = "Consistency", round = "System design", explanation = "A local transaction cannot atomically cover every independent service. Use idempotent commands, timeouts, and explicit pending states. Decide whether stock reservation precedes payment and how failures release resources.", code = "", mistake = "Describing compensation as a guaranteed reversal of every side effect.", rubric = listOf("Define workflow invariants", "Persist transitions and retry identity", "Plan compensation and reconciliation"), followups = listOf("What if payment succeeds after timeout?", "How do expired reservations behave?"), sourceIds = listOf("postgres-isolation", "http-semantics"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "system-design-hot-key", area = "System Design", level = 3, q = "A distributed store has one overloaded partition even though total capacity is low. What happened?", a = "A skewed access pattern or hot key can concentrate traffic. Measure per-partition load and choose a workload-specific mitigation.", subtopic = "Scaling", round = "Debugging", explanation = "Caching, batching, read replicas, or sharding a logical key may help, but each affects consistency and aggregation. Adding partitions does not automatically distribute one hot key.", code = "", mistake = "Using average cluster CPU as proof that no scaling problem exists.", rubric = listOf("Measure skewed load", "Identify the hot access pattern", "Evaluate consistency trade-offs"), followups = listOf("How do you handle a celebrity feed?", "When can key salting help?"), sourceIds = listOf("sre-overload"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "system-design-multiregion", area = "System Design", level = 4, q = "Choose a multi-region architecture for data that must remain correct during network partitions.", a = "Specify availability and consistency needs per operation, then decide where writes occur and how conflicts or outages are handled.", subtopic = "Distributed architecture", round = "System design", explanation = "Network partitions force trade-offs for coordinated operations. Distinguish read availability from write acceptance and define failover, data-loss objectives, and recovery verification. Avoid vague claims of universal strong consistency.", code = "", mistake = "Claiming all reads and writes remain strongly consistent and available under every partition.", rubric = listOf("Define per-operation guarantees", "Handle partition and failover behavior", "Validate recovery and conflicts"), followups = listOf("Which writes can be delayed?", "How do you handle stale reads?"), sourceIds = listOf("sre-book", "postgres-isolation"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "system-design-architecture-review", area = "System Design", level = 4, q = "How should an architecture review compare two plausible designs?", a = "Compare requirements, failure behavior, cost, operability, migration risk, and evidence, and record the decision and revisit conditions.", subtopic = "Engineering strategy", round = "Leadership", explanation = "Use workload estimates and prototypes to resolve key uncertainties. Include responsible owners and incremental validation. A decision record should explain assumptions, not just list chosen technologies.", code = "", mistake = "Selecting the more fashionable design without examining user or operational needs.", rubric = listOf("State assumptions and criteria", "Test the key uncertainty", "Record ownership and revisit triggers"), followups = listOf("Which risks require a prototype?", "What evidence would change the decision?"), sourceIds = listOf("sre-book"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview")
)
