private fun questionPack84(): List<Q> = listOf(
    Q(id = "tech-lead-review", area = "Tech Lead", level = 1, q = "What should a useful code review comment explain?", a = "State the observed issue, its consequence, and a concrete suggestion or question tied to the team's standards.", subtopic = "Collaboration", round = "Fundamentals", explanation = "Separate required fixes from preferences and review behavior, failure handling, and maintainability. Explain why a concern matters so the author can reason about a suitable solution.", code = "", mistake = "Requesting changes based only on personal style.", rubric = listOf("Identify a concrete issue", "Explain user or maintenance impact", "Distinguish requirement and preference"), followups = listOf("When should discussion move to a call?", "How do you handle a disputed comment?"), sourceIds = listOf("sre-book"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "tech-lead-handoff", area = "Tech Lead", level = 1, q = "A task is called finished but another engineer cannot safely operate it. What was missed?", a = "Completion should include agreed behavior, relevant validation, operational ownership, and documentation needed by the next user.", subtopic = "Team execution", round = "Debugging", explanation = "Use a clear definition of done appropriate to the work. Capture setup, known limitations, and failure recovery where necessary. Avoid paperwork that does not help maintenance or delivery.", code = "", mistake = "Equating merged code with a fully usable outcome.", rubric = listOf("Define completion criteria", "Provide required evidence", "Assign operational ownership"), followups = listOf("What belongs in a runbook?", "How do you avoid excessive ceremony?"), sourceIds = listOf("scrum-guide", "sre-book"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "tech-lead-mentoring", area = "Tech Lead", level = 2, q = "An engineer repeatedly struggles with a design task. How would you help without taking over?", a = "Identify the specific skill or context gap, agree on a smaller next step, and give feedback that enables independent progress.", subtopic = "Mentoring", round = "Leadership", explanation = "Ask them to explain assumptions and alternatives. Pair on one difficult boundary, then let them own the follow-through. Measure learning and confidence through behavior rather than vague praise.", code = "", mistake = "Finishing every difficult task for them.", rubric = listOf("Diagnose the specific gap", "Provide a bounded learning step", "Preserve ownership and follow-up"), followups = listOf("How do you handle a deadline?", "What if the same problem recurs?"), sourceIds = listOf("scrum-guide"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "tech-lead-disagreement", area = "Tech Lead", level = 2, q = "Two senior engineers disagree about an approach. How do you resolve it?", a = "Agree on requirements and decision criteria, gather evidence for the uncertain claims, and record an accountable decision.", subtopic = "Technical decisions", round = "Leadership", explanation = "Use a small experiment when it can answer the main uncertainty. Set a deadline and revisit conditions. Preserve dissenting concerns in the decision record without leaving ownership ambiguous.", code = "", mistake = "Settling the decision solely by rank or who argues longest.", rubric = listOf("Align on shared criteria", "Test the central uncertainty", "Record owner and revisit triggers"), followups = listOf("What if the decision is reversible?", "How do you support the losing proposal's author?"), sourceIds = listOf("sre-book"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "tech-lead-incident", area = "Tech Lead", level = 3, q = "Lead an incident where several services are failing and the cause is unclear.", a = "Establish coordination, stabilize user impact, assign investigation tasks, and keep a shared factual timeline.", subtopic = "Operations", round = "Leadership", explanation = "Separate incident command from detailed debugging when possible. Use explicit decision and communication ownership, then run a learning review with actionable follow-up. Avoid blaming individuals.", code = "", mistake = "Having every engineer change production independently.", rubric = listOf("Coordinate roles and evidence", "Prioritize stabilization", "Assign corrective follow-up"), followups = listOf("When do you roll back?", "How do you handle an uncertain diagnosis?"), sourceIds = listOf("sre-book"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "tech-lead-debt", area = "Tech Lead", level = 3, q = "How do you prioritize technical debt against requested product work?", a = "Describe the actual cost or risk, compare it with product value, and propose measurable bounded improvements.", subtopic = "Technical planning", round = "System design", explanation = "Tie debt to incidents, slow changes, maintenance cost, or strategic constraints. Include migration effort and opportunity cost. Fund small increments where they reduce repeated pain.", code = "", mistake = "Calling all old code debt without explaining its impact.", rubric = listOf("Quantify recurring cost or risk", "Compare options and effort", "Define measurable improvement"), followups = listOf("What debt can be accepted?", "How do you prevent it returning?"), sourceIds = listOf("sre-book", "scrum-guide"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "tech-lead-org-boundaries", area = "Tech Lead", level = 4, q = "Several teams block each other on shared services. What would you investigate before reorganizing?", a = "Map dependencies, ownership, decision delays, and actual workflows, then test whether clearer contracts or boundaries reduce coordination.", subtopic = "Architecture strategy", round = "Leadership", explanation = "An organization change alone does not resolve shared invariants or unclear APIs. Pilot the smallest useful boundary change and measure lead time, reliability, and operational accountability.", code = "", mistake = "Reorganizing teams without mapping the technical coupling.", rubric = listOf("Map real dependency costs", "Define accountable boundaries", "Validate a pilot with outcomes"), followups = listOf("When should a service be shared?", "What if one workflow crosses many teams?"), sourceIds = listOf("sre-book", "scrum-guide"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "tech-lead-strategy", area = "Tech Lead", level = 4, q = "Present a one-year platform strategy to product and engineering leadership.", a = "Connect user and business outcomes to current constraints, prioritized investments, success measures, and sequencing.", subtopic = "Engineering strategy", round = "Leadership", explanation = "Make assumptions, staffing, risks, and trade-offs explicit. Include incremental milestones and stop/revisit conditions. A strategy is a choice about effort, not a list of technologies.", code = "", mistake = "Presenting a technology roadmap without measurable outcomes.", rubric = listOf("Link investments to outcomes", "State capacity and trade-offs", "Define milestones and review triggers"), followups = listOf("How do you handle budget cuts?", "What would cause you to stop an initiative?"), sourceIds = listOf("sre-book"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview")
)
