private fun questionPack87(): List<Q> = listOf(
    Q(id = "testing-layers", area = "Testing and QA", level = 1, q = "How do unit, integration, and end-to-end tests complement each other?", a = "Unit tests isolate rules, integration tests verify real boundaries, and end-to-end tests exercise complete user workflows.", subtopic = "Testing strategy", round = "Fundamentals", explanation = "Choose tests by failure risk and feedback cost. An isolated test cannot prove database constraints or browser behavior. A few critical workflow tests should complement fast focused checks.", code = "", mistake = "Assuming one test layer can verify the entire product.", rubric = listOf("Map tests to risks", "Identify real boundary needs", "Balance feedback speed and coverage"), followups = listOf("Which tests should use a real database?", "When is a mock useful?"), sourceIds = listOf("playwright", "pytest"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "testing-isolation", area = "Testing and QA", level = 1, q = "A test passes alone but fails after another test. What would you investigate?", a = "Look for shared state, order dependence, leaked resources, and incomplete setup or cleanup.", subtopic = "Test reliability", round = "Debugging", explanation = "Give tests independent fixtures and unique data where needed. Check global configuration, clocks, database state, and asynchronous work that outlives the test.", code = "", mistake = "Fixing the execution order instead of removing the dependency.", rubric = listOf("Find shared state", "Provide deterministic setup/cleanup", "Stop leaked asynchronous work"), followups = listOf("How should database fixtures reset?", "What if tests run in parallel?"), sourceIds = listOf("pytest", "playwright"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "testing-flaky-ui", area = "Testing and QA", level = 2, q = "A browser test needs longer sleeps every month. How would you improve it?", a = "Use stable user-facing locators and wait for observable conditions with the framework rather than arbitrary time delays.", subtopic = "UI automation", round = "Debugging", explanation = "Inspect traces and isolate external services when appropriate. Keep test data predictable and assert the user outcome. Longer sleeps can hide a real timing or ownership defect.", code = "", mistake = "Making tests slower until failures become rare.", rubric = listOf("Use resilient locators", "Wait for meaningful conditions", "Diagnose with traces and controlled data"), followups = listOf("When should an API be stubbed?", "What if the UI never reaches readiness?"), sourceIds = listOf("playwright"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "testing-boundaries", area = "Testing and QA", level = 2, q = "Design tests for a paginated endpoint with tenant permissions.", a = "Cover ordering, cursor boundaries, empty results, invalid cursors, and cross-tenant access with realistic persisted data.", subtopic = "Test design", round = "Coding", explanation = "Test tied sort keys and records added between pages. Assert no missing or duplicate records under the documented semantics, and verify unauthorized reads are rejected at the real service boundary.", code = "", mistake = "Testing only a successful first page.", rubric = listOf("Exercise cursor edge cases", "Validate tenant denial", "Use representative persisted ordering"), followups = listOf("How do deletes affect pagination?", "What belongs in a contract test?"), sourceIds = listOf("owasp-testing", "postgres-indexes"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "testing-failure-tests", area = "Testing and QA", level = 3, q = "How would you test a workflow that writes data and publishes an event?", a = "Inject failures before and after commits and publication, then verify durable state and safe replay.", subtopic = "Reliability testing", round = "System design", explanation = "Use real transactional storage for atomicity checks and controlled broker failures for delivery behavior. Include duplicates and poison events. Avoid relying only on mocks that assume the transaction works.", code = "", mistake = "Calling a happy-path unit test proof of atomic delivery.", rubric = listOf("Test crash boundaries", "Verify replay and duplicates", "Inspect durable business invariants"), followups = listOf("How do you test outbox lag?", "Which failures require an integration environment?"), sourceIds = listOf("pytest", "postgres-isolation"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "testing-performance", area = "Testing and QA", level = 3, q = "A load test reports good average latency but users complain. What should be checked?", a = "Inspect tail latency, error rates, workload realism, concurrency, and whether the generator actually reaches the intended load.", subtopic = "Performance testing", round = "Debugging", explanation = "Include slow dependencies, realistic data sizes, and sustained runs. Averages hide outliers and successful-request-only reports can hide timeouts. Measure recovery after overload.", code = "", mistake = "Ignoring failed or timed-out requests in latency conclusions.", rubric = listOf("Measure tails and failures", "Validate realistic traffic", "Test sustained and degraded behavior"), followups = listOf("Can the load generator be the bottleneck?", "What changes after caches warm?"), sourceIds = listOf("sre-overload"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "testing-quality-policy", area = "Testing and QA", level = 4, q = "Set release quality gates for many teams without blocking every change on slow tests.", a = "Use risk-based gates, fast local feedback, targeted integration checks, and ownership of flaky or slow tests.", subtopic = "Engineering strategy", round = "Leadership", explanation = "Track escaped defects and test reliability, not just pass count or coverage. Define exceptions and emergency release paths with follow-up obligations. Remove checks that add cost without evidence of value.", code = "", mistake = "Treating code coverage as a complete measure of product quality.", rubric = listOf("Align checks with release risk", "Assign reliability ownership", "Measure escaped defects and feedback time"), followups = listOf("When can a gate be bypassed?", "How do you quarantine a flaky test responsibly?"), sourceIds = listOf("playwright", "pytest"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview"),
    Q(id = "testing-automation", area = "Testing and QA", level = 4, q = "Design a test automation platform for mobile, web, and APIs.", a = "Share data and reporting contracts while keeping platform-specific execution and locators behind clear boundaries.", subtopic = "Architecture", round = "System design", explanation = "Provide deterministic environments, diagnostics, secret handling, parallel isolation, and ownership. Avoid one abstraction that hides important platform behavior. Measure maintenance and signal quality.", code = "", mistake = "Building a universal wrapper that makes failures impossible to diagnose.", rubric = listOf("Define shared contracts and platform boundaries", "Ensure isolated reproducible runs", "Provide actionable diagnostics"), followups = listOf("How are fixtures versioned?", "What should be shared across platforms?"), sourceIds = listOf("playwright", "pytest", "android-testing"), version = 1, reviewedAt = "2026-10-05", origin = "PrepDesk original; linked documentation is learning material, not a claim of an actual company interview")
)
